    {"offset": {"line": 4, "column": 0}, "map": {"version":3,"sources":["file:///C:/Users/Steve%20Smart/Downloads/preventive-maintenance-fullstack/components/Dashboard.tsx"],"sourcesContent":["\"use client\";\r\n\r\nimport { useEffect, useMemo, useState } from \"react\";\r\nimport type { FormEvent } from \"react\";\r\nimport { useRouter } from \"next/navigation\";\r\nimport {\r\n  AlertTriangle,\r\n  BarChart3,\r\n  Building2,\r\n  CalendarDays,\r\n  CalendarClock,\r\n  CheckCircle2,\r\n  ChevronRight,\r\n  ClipboardCheck,\r\n  Clock3,\r\n  Database,\r\n  Download,\r\n  FileSpreadsheet,\r\n  Layers,\r\n  LogIn,\r\n  MonitorCog,\r\n  Pencil,\r\n  PieChart,\r\n  Plus,\r\n  RefreshCw,\r\n  RotateCcw,\r\n  Save,\r\n  Search,\r\n  ShieldCheck,\r\n  Trash2,\r\n  TrendingUp,\r\n  Upload,\r\n  Wrench,\r\n  X,\r\n} from \"lucide-react\";\r\nimport * as XLSX from \"xlsx\";\r\nimport {\r\n  Bar,\r\n  BarChart,\r\n  CartesianGrid,\r\n  Cell,\r\n  Legend,\r\n  Pie,\r\n  PieChart as RechartsPieChart,\r\n  ResponsiveContainer,\r\n  Tooltip,\r\n  XAxis,\r\n  YAxis,\r\n} from \"recharts\";\r\n\r\nimport { supabase } from \"@/lib/supabase-browser\";\r\nimport { getPMStatus } from \"@/lib/pm\";\r\nimport type {\r\n  Equipment,\r\n  PMSchedule,\r\n  PMStatus,\r\n  UserRole,\r\n  Section,\r\n} from \"@/lib/types\";\r\n\r\nconst emptyStats: Record<PMStatus, number> = {\r\n  Done: 0,\r\n  Overdue: 0,\r\n  Pending: 0,\r\n  Scheduled: 0,\r\n  \"N/A\": 0,\r\n};\r\n\r\ntype EquipmentForm = {\r\n  sno: string;\r\n  department: string;\r\n  inventory_no: string;\r\n  location: string;\r\n  equipment_name: string;\r\n  model: string;\r\n  serial_no: string;\r\n  make: string;\r\n  campus: string;\r\n  contract: string;\r\n  pm1_date: string;\r\n  pm2_date: string;\r\n  pm3_date: string;\r\n  pm4_date: string;\r\n  pm1_na: boolean;\r\n  pm2_na: boolean;\r\n  pm3_na: boolean;\r\n  pm4_na: boolean;\r\n};\r\n\r\nconst emptyEquipmentForm: EquipmentForm = {\r\n  sno: \"\",\r\n  department: \"\",\r\n  inventory_no: \"\",\r\n  location: \"\",\r\n  equipment_name: \"\",\r\n  model: \"\",\r\n  serial_no: \"\",\r\n  make: \"\",\r\n  campus: \"\",\r\n  contract: \"\",\r\n  pm1_date: \"\",\r\n  pm2_date: \"\",\r\n  pm3_date: \"\",\r\n  pm4_date: \"\",\r\n  pm1_na: false,\r\n  pm2_na: false,\r\n  pm3_na: false,\r\n  pm4_na: false,\r\n};\r\n\r\nfunction fmtDate(value: string | Date | null) {\r\n  if (!value) return \"N/A\";\r\n\r\n  return new Intl.DateTimeFormat(\"en-GB\", {\r\n    day: \"2-digit\",\r\n    month: \"2-digit\",\r\n    year: \"numeric\",\r\n  }).format(\r\n    value instanceof Date ? value : new Date(`${value}T00:00:00`)\r\n  );\r\n}\r\n\r\nfunction cleanDate(value: unknown): string {\r\n  if (!value) return \"\";\r\n\r\n  if (value instanceof Date) {\r\n    return value.toISOString().slice(0, 10);\r\n  }\r\n\r\n  if (typeof value === \"number\") {\r\n    const date = XLSX.SSF.parse_date_code(value);\r\n    if (date) {\r\n      return `${date.y}-${String(date.m).padStart(2, \"0\")}-${String(\r\n        date.d\r\n      ).padStart(2, \"0\")}`;\r\n    }\r\n  }\r\n\r\n  const text = String(value).trim();\r\n\r\n  if (/^\\d{4}-\\d{2}-\\d{2}$/.test(text)) {\r\n    return text;\r\n  }\r\n\r\n  const parsed = new Date(text);\r\n  if (!Number.isNaN(parsed.getTime())) {\r\n    return parsed.toISOString().slice(0, 10);\r\n  }\r\n\r\n  return \"\";\r\n}\r\n\r\nfunction excelValue(row: Record<string, unknown>, names: string[]) {\r\n  const keys = Object.keys(row);\r\n\r\n  for (const name of names) {\r\n    const found = keys.find(\r\n      (key) =>\r\n        key.trim().toLowerCase().replace(/[ .-]+/g, \"_\") ===\r\n        name.toLowerCase().replace(/[ .-]+/g, \"_\")\r\n    );\r\n\r\n    if (found !== undefined) {\r\n      return row[found];\r\n    }\r\n  }\r\n\r\n  return \"\";\r\n}\r\n\r\nexport default function Dashboard() {\r\n  const router = useRouter();\r\n  const [equipment, setEquipment] = useState<Equipment[]>([]);\r\n  const [search, setSearch] = useState(\"\");\r\n  const [equipmentFilter, setEquipmentFilter] = useState(\"All\");\r\n  const [sectionFilter, setSectionFilter] = useState(\"All\");\r\n  const [campus, setCampus] = useState(\"All\");\r\n  const [department, setDepartment] = useState(\"All\");\r\n  const [contract, setContract] = useState(\"All\");\r\n  const [status, setStatus] = useState(\"Any status\");\r\n  const [pmNumber, setPmNumber] = useState(\"All\");\r\n  const [scheduleSearch, setScheduleSearch] = useState(\"\");\r\n\r\n  const [dataLoading, setDataLoading] = useState(true);\r\n  const [connected, setConnected] = useState(true);\r\n\r\n  const [userEmail, setUserEmail] = useState<string | null>(null);\r\n  const [userRole, setUserRole] = useState<UserRole | null>(null);\r\n  const [userSection, setUserSection] = useState<Section | null>(null);\r\n\r\n  const [authOpen, setAuthOpen] = useState(false);\r\n  const [loginType, setLoginType] = useState<\"loginId\" | \"email\">(\r\n    \"loginId\"\r\n  );\r\n  const [loginId, setLoginId] = useState(\"\");\r\n  const [email, setEmail] = useState(\"\");\r\n  const [password, setPassword] = useState(\"\");\r\n  const [authMessage, setAuthMessage] = useState(\"\");\r\n  const [loading, setLoading] = useState(false);\r\n  const [error, setError] = useState(\"\");\r\n  const [showUserManagement, setShowUserManagement] = useState(false);\r\n  const [newUser, setNewUser] = useState({\r\n    login_id: \"\",\r\n    email: \"\",\r\n    password: \"\",\r\n    role: \"technician\",\r\n    section: \"HIGH_END_RADIOLOGY\",\r\n  });\r\n  const [creatingUser, setCreatingUser] = useState(false);\r\n  const [userMessage, setUserMessage] = useState(\"\");\r\n\r\n  const [showEquipmentForm, setShowEquipmentForm] = useState(false);\r\n  const [showDueSoon, setShowDueSoon] = useState(false);\r\n  const [showOverdue, setShowOverdue] = useState(false);\r\n  const [editingEquipment, setEditingEquipment] =\r\n    useState<Equipment | null>(null);\r\n\r\n  const [equipmentForm, setEquipmentForm] =\r\n    useState<EquipmentForm>(emptyEquipmentForm);\r\n\r\n  const [importing, setImporting] = useState(false);\r\n\r\n  const [editingPM, setEditingPM] = useState<PMSchedule | null>(null);\r\n  const [pmDate, setPmDate] = useState(\"\");\r\n\r\n  const isSuperAdmin = userRole === \"SUPER_ADMIN\";\r\n  const isSuperViewer = userRole === \"SUPER_VIEWER\";\r\n  const isSectionAdmin = userRole === \"section_admin\";\r\n  const isTechnician = userRole === \"technician\";\r\n\r\n  const canManageEquipment =\r\n    isSuperAdmin || isSectionAdmin;\r\n\r\n  const canUpdatePM =\r\n    isSuperAdmin || isTechnician;\r\n\r\n  function canAccessEquipment(item: Equipment) {\r\n    if (isSuperAdmin || isSuperViewer) {\r\n      return true;\r\n    }\r\n\r\n    return Boolean(\r\n      userSection &&\r\n        item.section &&\r\n        item.section === userSection\r\n    );\r\n  }\r\n\r\n  function canManageThisEquipment(item: Equipment) {\r\n    if (isSuperAdmin) {\r\n      return true;\r\n    }\r\n\r\n    return (\r\n      isSectionAdmin &&\r\n      userSection !== null &&\r\n      item.section === userSection\r\n    );\r\n  }\r\n\r\n  function canUpdateThisPM(item: Equipment) {\r\n    if (isSuperAdmin) {\r\n      return true;\r\n    }\r\n\r\n    return (\r\n      isTechnician &&\r\n      userSection !== null &&\r\n      item.section === userSection\r\n    );\r\n  }\r\n\r\n  const getSectionHeading = () => {\r\n    if (\r\n      userRole === \"SUPER_ADMIN\" ||\r\n      userRole === \"SUPER_VIEWER\"\r\n    ) {\r\n      return getSectionLabel(sectionFilter).toUpperCase();\r\n    }\r\n\r\n    return userSection\r\n      ? getSectionLabel(userSection).toUpperCase()\r\n      : \"SECTION\";\r\n  };\r\n\r\n  async function createUser() {\r\n    if (!newUser.login_id.trim()) {\r\n      setUserMessage(\"Login ID is required\");\r\n      return;\r\n    }\r\n\r\n    if (!newUser.email.trim()) {\r\n      setUserMessage(\"Email is required\");\r\n      return;\r\n    }\r\n\r\n    if (!newUser.password) {\r\n      setUserMessage(\"Password is required\");\r\n      return;\r\n    }\r\n\r\n    setCreatingUser(true);\r\n    setUserMessage(\"\");\r\n\r\n    try {\r\n      const response = await fetch(\"/api/admin/create-user\", {\r\n        method: \"POST\",\r\n        headers: {\r\n          \"Content-Type\": \"application/json\",\r\n        },\r\n        body: JSON.stringify(newUser),\r\n      });\r\n\r\n      const result = await response.json();\r\n\r\n      if (!response.ok) {\r\n        throw new Error(\r\n          result.error || \"Failed to create user\"\r\n        );\r\n      }\r\n\r\n      setUserMessage(\r\n        `User ${newUser.login_id} created successfully`\r\n      );\r\n\r\n      setNewUser({\r\n        login_id: \"\",\r\n        email: \"\",\r\n        password: \"\",\r\n        role: \"technician\",\r\n        section: \"HIGH_END_RADIOLOGY\",\r\n      });\r\n    } catch (error) {\r\n      setUserMessage(\r\n        error instanceof Error\r\n          ? error.message\r\n          : \"Failed to create user\"\r\n      );\r\n    } finally {\r\n      setCreatingUser(false);\r\n    }\r\n  }\r\n\r\n  async function loadUserRole() {\r\n    const {\r\n      data: { user },\r\n    } = await supabase.auth.getUser();\r\n\r\n    if (!user) {\r\n      setUserEmail(\"\");\r\n      setUserRole(null);\r\n      setUserSection(null);\r\n      return;\r\n    }\r\n\r\n    setUserEmail(user.email ?? \"\");\r\n\r\n    const { data, error } = await supabase\r\n      .from(\"user_roles\")\r\n      .select(\"role, section\")\r\n      .eq(\"user_id\", user.id)\r\n      .maybeSingle();\r\n\r\n    if (error) {\r\n      console.error(\"Failed to load user role:\", error);\r\n      setUserRole(null);\r\n      setUserSection(null);\r\n      return;\r\n    }\r\n\r\n    setUserRole((data?.role as UserRole) ?? null);\r\n    setUserSection((data?.section as Section) ?? null);\r\n  }\r\n\r\n  async function load() {\r\n    setDataLoading(true);\r\n\r\n    const {\r\n      data: { user },\r\n    } = await supabase.auth.getUser();\r\n\r\n    setUserEmail(user?.email ?? null);\r\n\r\n    if (!user) {\r\n      setEquipment([]);\r\n      setConnected(true);\r\n      setDataLoading(false);\r\n      return;\r\n    }\r\n\r\n    const { data, error } = await supabase\r\n      .from(\"equipment\")\r\n      .select(\"*, pm_schedules(*)\")\r\n      .order(\"sno\");\r\n\r\n    if (error) {\r\n      console.error(error);\r\n      setConnected(false);\r\n      setEquipment([]);\r\n    } else {\r\n      setConnected(true);\r\n      setEquipment((data ?? []) as Equipment[]);\r\n    }\r\n\r\n    setDataLoading(false);\r\n  }\r\n\r\n  useEffect(() => {\r\n    load();\r\n    loadUserRole();\r\n\r\n    const channel = supabase\r\n      .channel(\"pm-dashboard\")\r\n      .on(\r\n        \"postgres_changes\",\r\n        {\r\n          event: \"*\",\r\n          schema: \"public\",\r\n          table: \"pm_schedules\",\r\n        },\r\n        load\r\n      )\r\n      .on(\r\n        \"postgres_changes\",\r\n        {\r\n          event: \"*\",\r\n          schema: \"public\",\r\n          table: \"equipment\",\r\n        },\r\n        load\r\n      )\r\n      .subscribe();\r\n\r\n    return () => {\r\n      supabase.removeChannel(channel);\r\n    };\r\n  }, []);\r\n\r\n  useEffect(() => {\r\n    if (\r\n      userRole !== \"SUPER_ADMIN\" &&\r\n      userRole !== \"SUPER_VIEWER\" &&\r\n      userSection\r\n    ) {\r\n      setSectionFilter(userSection);\r\n    }\r\n  }, [userRole, userSection]);\r\n\r\n  const sectionScopedEquipment = useMemo(() => {\r\n    if (\r\n      userRole === \"SUPER_ADMIN\" ||\r\n      userRole === \"SUPER_VIEWER\"\r\n    ) {\r\n      if (sectionFilter === \"All\") {\r\n        return equipment;\r\n      }\r\n\r\n      return equipment.filter(\r\n        (e) => e.section === sectionFilter\r\n      );\r\n    }\r\n\r\n    if (userSection) {\r\n      return equipment.filter(\r\n        (e) => e.section === userSection\r\n      );\r\n    }\r\n\r\n    return [];\r\n  }, [\r\n    equipment,\r\n    sectionFilter,\r\n    userRole,\r\n    userSection,\r\n  ]);\r\n\r\n  const filtered = useMemo(() => {\r\n    const q = search.toLowerCase().trim();\r\n\r\n    return sectionScopedEquipment.filter((e) => {\r\n      const text = [\r\n        e.sno,\r\n        e.department,\r\n        e.inventory_no,\r\n        e.location,\r\n        e.equipment_name,\r\n        e.model,\r\n        e.serial_no,\r\n        e.make,\r\n        e.campus,\r\n        e.contract,\r\n      ]\r\n        .join(\" \")\r\n        .toLowerCase();\r\n\r\n      if (q && !text.includes(q)) return false;\r\n      if (\r\n        equipmentFilter !== \"All\" &&\r\n        e.equipment_name !== equipmentFilter\r\n      ) {\r\n        return false;\r\n      }\r\n\r\n      if (campus !== \"All\" && e.campus !== campus) return false;\r\n      if (department !== \"All\" && e.department !== department) return false;\r\n      if (contract !== \"All\" && e.contract !== contract) return false;\r\n\r\n      const activePMs = (e.pm_schedules ?? []).filter(\r\n        (pm) => pm.scheduled_date !== null\r\n      );\r\n\r\n      if (pmNumber !== \"All\") {\r\n        const selectedPM = activePMs.find(\r\n          (pm) => pm.pm_no === Number(pmNumber)\r\n        );\r\n\r\n        if (!selectedPM) return false;\r\n        if (\r\n          status !== \"Any status\" &&\r\n          getPMStatus(selectedPM) !== status\r\n        ) {\r\n          return false;\r\n        }\r\n      } else if (\r\n        status !== \"Any status\" &&\r\n        !activePMs.some((pm) => getPMStatus(pm) === status)\r\n      ) {\r\n        return false;\r\n      }\r\n\r\n      return true;\r\n    });\r\n  }, [\r\n    sectionScopedEquipment,\r\n    search,\r\n    equipmentFilter,\r\n    campus,\r\n    department,\r\n    contract,\r\n    status,\r\n    pmNumber,\r\n  ]);\r\n\r\n  const scheduleFiltered = useMemo(() => {\r\n    const q = scheduleSearch.toLowerCase().trim();\r\n\r\n    if (!q) {\r\n      return filtered;\r\n    }\r\n\r\n    return filtered.filter((e) => {\r\n      const searchableText = [\r\n        e.sno,\r\n        e.department,\r\n        e.inventory_no,\r\n        e.location,\r\n        e.equipment_name,\r\n        e.model,\r\n        e.serial_no,\r\n        e.make,\r\n        e.campus,\r\n        e.contract,\r\n      ]\r\n        .filter(Boolean)\r\n        .join(\" \")\r\n        .toLowerCase();\r\n\r\n      return searchableText.includes(q);\r\n    });\r\n  }, [filtered, scheduleSearch]);\r\n\r\n  const pmStatusStats = useMemo(() => {\r\n    const pms = filtered.flatMap((e) =>\r\n      (e.pm_schedules ?? []).filter(\r\n        (pm) => pm.scheduled_date !== null\r\n      )\r\n    );\r\n\r\n    return {\r\n      Done: pms.filter((pm) => getPMStatus(pm) === \"Done\").length,\r\n      Overdue: pms.filter((pm) => getPMStatus(pm) === \"Overdue\").length,\r\n      Pending: pms.filter((pm) => getPMStatus(pm) === \"Pending\").length,\r\n      Scheduled: pms.filter((pm) => getPMStatus(pm) === \"Scheduled\").length,\r\n    };\r\n  }, [filtered]);\r\n\r\n  const pmCounters = useMemo(() => {\r\n    const pms = filtered.flatMap((e) =>\r\n      (e.pm_schedules ?? []).filter(\r\n        (pm) => pm.scheduled_date !== null\r\n      )\r\n    );\r\n\r\n    const dueSoon = pms.filter(\r\n      (pm) => getPMStatus(pm) === \"Pending\"\r\n    ).length;\r\n\r\n    const overdue = pms.filter(\r\n      (pm) => getPMStatus(pm) === \"Overdue\"\r\n    ).length;\r\n\r\n    return {\r\n      dueSoon,\r\n      overdue,\r\n      yetToBeDone: dueSoon + overdue,\r\n    };\r\n  }, [filtered]);\r\n\r\n  const filteredPMs = useMemo(\r\n    () =>\r\n      filtered.flatMap((e) =>\r\n        (e.pm_schedules ?? []).filter(\r\n          (pm) => pm.scheduled_date !== null\r\n        )\r\n      ),\r\n    [filtered]\r\n  );\r\n\r\n  const filteredCounts = {\r\n    ...pmStatusStats,\r\n    total:\r\n      pmStatusStats.Done +\r\n      pmStatusStats.Overdue +\r\n      pmStatusStats.Pending +\r\n      pmStatusStats.Scheduled,\r\n    NA: filtered.reduce(\r\n      (total, e) =>\r\n        total +\r\n        (e.pm_schedules ?? []).filter(\r\n          (pm) => pm.scheduled_date === null\r\n        ).length,\r\n      0\r\n    ),\r\n  };\r\n\r\n  const counts = pmStatusStats;\r\n  const allPMs = filteredPMs;\r\n\r\n  const overallCompliance = useMemo(() => {\r\n    const pms = filtered.flatMap((e) =>\r\n      (e.pm_schedules ?? []).filter(\r\n        (pm) => pm.scheduled_date !== null\r\n      )\r\n    );\r\n\r\n    const done = pms.filter(\r\n      (pm) => getPMStatus(pm) === \"Done\"\r\n    ).length;\r\n\r\n    return pms.length > 0\r\n      ? Math.round((done / pms.length) * 100)\r\n      : 0;\r\n  }, [filtered]);\r\n\r\n  const complianceDone = pmStatusStats.Done;\r\n  const complianceTotal =\r\n    pmStatusStats.Done +\r\n    pmStatusStats.Overdue +\r\n    pmStatusStats.Pending +\r\n    pmStatusStats.Scheduled;\r\n\r\n  const monthlyCompliance = useMemo(() => {\r\n    const now = new Date();\r\n\r\n    const monthStart = new Date(\r\n      now.getFullYear(),\r\n      now.getMonth(),\r\n      1\r\n    );\r\n\r\n    const nextMonthStart = new Date(\r\n      now.getFullYear(),\r\n      now.getMonth() + 1,\r\n      1\r\n    );\r\n\r\n    const monthPMs = filtered.flatMap((e) =>\r\n      (e.pm_schedules ?? []).filter((pm) => {\r\n        if (!pm.scheduled_date) return false;\r\n\r\n        const scheduled = new Date(\r\n          `${pm.scheduled_date}T00:00:00`\r\n        );\r\n\r\n        return (\r\n          scheduled >= monthStart &&\r\n          scheduled < nextMonthStart\r\n        );\r\n      })\r\n    );\r\n\r\n    const done = monthPMs.filter(\r\n      (pm) => getPMStatus(pm) === \"Done\"\r\n    ).length;\r\n\r\n    return {\r\n      done,\r\n      total: monthPMs.length,\r\n      compliance:\r\n        monthPMs.length > 0\r\n          ? Math.round((done / monthPMs.length) * 100)\r\n          : 0,\r\n    };\r\n  }, [filtered]);\r\n\r\n  const filteredCampuses = [\r\n    ...new Set(\r\n      filtered\r\n        .map((e) => e.campus)\r\n        .filter(\r\n          (value): value is string => Boolean(value)\r\n        )\r\n    ),\r\n  ].sort();\r\n\r\n  const compliancePercentage = overallCompliance;\r\n\r\n  const dueSoonRows = filtered\r\n    .flatMap((equipment) =>\r\n      (equipment.pm_schedules ?? []).map((pm) => ({\r\n        equipment,\r\n        pm,\r\n      }))\r\n    )\r\n    .filter(\r\n      ({ pm }) =>\r\n        pm.scheduled_date !== null &&\r\n        getPMStatus(pm) === \"Pending\"\r\n    )\r\n    .sort(\r\n      (a, b) =>\r\n        new Date(`${a.pm.scheduled_date}T00:00:00`).getTime() -\r\n        new Date(`${b.pm.scheduled_date}T00:00:00`).getTime()\r\n    );\r\n\r\n  const overdueRows = filtered\r\n    .flatMap((equipment) =>\r\n      (equipment.pm_schedules ?? []).map((pm) => ({\r\n        equipment,\r\n        pm,\r\n      }))\r\n    )\r\n    .filter(\r\n      ({ pm }) =>\r\n        pm.scheduled_date !== null &&\r\n        getPMStatus(pm) === \"Overdue\"\r\n    )\r\n    .sort(\r\n      (a, b) =>\r\n        new Date(`${a.pm.scheduled_date}T00:00:00`).getTime() -\r\n        new Date(`${b.pm.scheduled_date}T00:00:00`).getTime()\r\n    );\r\n\r\n  const campusPerformance = filteredCampuses.map((campusName) => {\r\n    const campusPMs = filtered\r\n      .filter((e) => e.campus === campusName)\r\n      .flatMap((e) => e.pm_schedules ?? [])\r\n      .filter((pm) => pm.scheduled_date !== null);\r\n    const done = campusPMs.filter(\r\n      (pm) => getPMStatus(pm) === \"Done\"\r\n    ).length;\r\n\r\n    return {\r\n      name: campusName,\r\n      total: campusPMs.length,\r\n      percentage: campusPMs.length\r\n        ? Math.round((done / campusPMs.length) * 100)\r\n        : 0,\r\n    };\r\n  });\r\n\r\n  const departmentPerformance = [\r\n    ...new Set(filtered.map((e) => e.department).filter(Boolean)),\r\n  ].map((departmentName) => {\r\n    const departmentPMs = filtered\r\n      .filter((e) => e.department === departmentName)\r\n      .flatMap((e) => e.pm_schedules ?? [])\r\n      .filter((pm) => pm.scheduled_date !== null);\r\n\r\n    return {\r\n      name: departmentName,\r\n      total: departmentPMs.length,\r\n      done: departmentPMs.filter(\r\n        (pm) => getPMStatus(pm) === \"Done\"\r\n      ).length,\r\n    };\r\n  });\r\n\r\n  const pmDistribution = [1, 2, 3, 4].map((pmNo) => ({\r\n    name: `PM ${pmNo}`,\r\n    total: filteredPMs.filter((pm) => pm.pm_no === pmNo).length,\r\n    done: filteredPMs.filter(\r\n      (pm) => pm.pm_no === pmNo && getPMStatus(pm) === \"Done\"\r\n    ).length,\r\n  }));\r\n\r\n  const monthlyTrend = Array.from({ length: 6 }, (_, index) => {\r\n    const date = new Date();\r\n    date.setDate(1);\r\n    date.setMonth(date.getMonth() - (5 - index));\r\n    const month = date.toISOString().slice(0, 7);\r\n    const value = filteredPMs.filter(\r\n      (pm) =>\r\n        getPMStatus(pm) === \"Done\" &&\r\n        pm.completed_date?.startsWith(month)\r\n    ).length;\r\n\r\n    return {\r\n      name: date.toLocaleDateString(\"en-US\", { month: \"short\" }),\r\n      value,\r\n      percentage: value\r\n        ? Math.round((value / Math.max(1, filteredCounts.Done)) * 100)\r\n        : 0,\r\n    };\r\n  });\r\n\r\n  const pmStatusData = [\r\n    { name: \"Done\", value: filteredCounts.Done },\r\n    { name: \"Due Soon\", value: filteredCounts.Pending },\r\n    { name: \"Overdue\", value: filteredCounts.Overdue },\r\n    { name: \"Scheduled\", value: filteredCounts.Scheduled },\r\n  ];\r\n\r\n  const campusPMData = filteredCampuses.map((campusName) => {\r\n    const pms = filtered\r\n      .filter((e) => e.campus === campusName)\r\n      .flatMap((e) => e.pm_schedules ?? [])\r\n      .filter((pm) => pm.scheduled_date !== null);\r\n\r\n    return {\r\n      campus: campusName,\r\n      Done: pms.filter((pm) => getPMStatus(pm) === \"Done\").length,\r\n      \"Due Soon\": pms.filter((pm) => getPMStatus(pm) === \"Pending\").length,\r\n      Overdue: pms.filter((pm) => getPMStatus(pm) === \"Overdue\").length,\r\n      Scheduled: pms.filter((pm) => getPMStatus(pm) === \"Scheduled\").length,\r\n    };\r\n  });\r\n\r\n  const departmentPMData = departmentPerformance.map((item) => {\r\n    const pms = filtered\r\n      .filter((e) => e.department === item.name)\r\n      .flatMap((e) => e.pm_schedules ?? [])\r\n      .filter((pm) => pm.scheduled_date !== null);\r\n\r\n    return {\r\n      department: item.name,\r\n      Done: pms.filter((pm) => getPMStatus(pm) === \"Done\").length,\r\n      \"Due Soon\": pms.filter((pm) => getPMStatus(pm) === \"Pending\").length,\r\n      Overdue: pms.filter((pm) => getPMStatus(pm) === \"Overdue\").length,\r\n      Scheduled: pms.filter((pm) => getPMStatus(pm) === \"Scheduled\").length,\r\n    };\r\n  });\r\n\r\n  const campusComplianceData = campusPerformance.map((item) => ({\r\n    campus: item.name,\r\n    compliance: item.percentage,\r\n  }));\r\n\r\n  const campuses = useMemo(\r\n    () =>\r\n      Array.from(\r\n        new Set(\r\n          sectionScopedEquipment\r\n            .map((e) => e.campus)\r\n            .filter(\r\n              (value): value is string => Boolean(value)\r\n            )\r\n        )\r\n      ).sort(),\r\n    [sectionScopedEquipment]\r\n  );\r\n\r\n  const departments = useMemo(\r\n    () =>\r\n      Array.from(\r\n        new Set(\r\n          sectionScopedEquipment\r\n            .map((e) => e.department)\r\n            .filter(Boolean)\r\n        )\r\n      ).sort(),\r\n    [sectionScopedEquipment]\r\n  );\r\n\r\n  const contracts = useMemo(\r\n    () =>\r\n      Array.from(\r\n        new Set(\r\n          sectionScopedEquipment\r\n            .map((e) => e.contract)\r\n            .filter(\r\n              (value): value is string => Boolean(value)\r\n            )\r\n        )\r\n      ).sort(),\r\n    [sectionScopedEquipment]\r\n  );\r\n\r\n  const equipmentNames = useMemo(\r\n    () =>\r\n      Array.from(\r\n        new Set(\r\n          sectionScopedEquipment\r\n            .map((e) => e.equipment_name)\r\n            .filter(Boolean)\r\n        )\r\n      ).sort(),\r\n    [sectionScopedEquipment]\r\n  );\r\n\r\n  async function updatePM(pm: PMSchedule, completed: boolean) {\r\n    if (!canUpdatePM) {\r\n      return;\r\n    }\r\n\r\n    const response = await fetch(`/api/pm/${pm.id}`, {\r\n      method: \"PATCH\",\r\n      headers: {\r\n        \"Content-Type\": \"application/json\",\r\n      },\r\n      body: JSON.stringify({\r\n        completed,\r\n      }),\r\n    });\r\n\r\n    if (!response.ok) {\r\n      const data = await response.json();\r\n      alert(data.error ?? \"Could not update PM.\");\r\n      return;\r\n    }\r\n\r\n    await load();\r\n  }\r\n\r\n  async function markAll(e: Equipment) {\r\n    if (!canUpdateThisPM(e)) {\r\n      return;\r\n    }\r\n\r\n    const pending = (e.pm_schedules ?? []).filter(\r\n      (pm) => pm.scheduled_date !== null && !pm.completed_date\r\n    );\r\n\r\n    for (const pm of pending) {\r\n      await updatePM(pm, true);\r\n    }\r\n\r\n    await load();\r\n  }\r\n\r\n  function openEquipmentForm(e?: Equipment) {\r\n    setEditingEquipment(e ?? null);\r\n\r\n    if (e) {\r\n      const getPMDate = (number: number) =>\r\n        e.pm_schedules?.find((pm) => pm.pm_no === number)\r\n          ?.scheduled_date ?? \"\";\r\n      const getPMNA = (number: number) =>\r\n        e.pm_schedules?.find((pm) => pm.pm_no === number)\r\n          ?.scheduled_date === null;\r\n\r\n      setEquipmentForm({\r\n        sno: String(e.sno ?? \"\"),\r\n        department: e.department ?? \"\",\r\n        inventory_no: e.inventory_no ?? \"\",\r\n        location: e.location ?? \"\",\r\n        equipment_name: e.equipment_name ?? \"\",\r\n        model: e.model ?? \"\",\r\n        serial_no: e.serial_no ?? \"\",\r\n        make: e.make ?? \"\",\r\n        campus: e.campus ?? \"\",\r\n        contract: e.contract ?? \"\",\r\n        pm1_date: getPMDate(1),\r\n        pm2_date: getPMDate(2),\r\n        pm3_date: getPMDate(3),\r\n        pm4_date: getPMDate(4),\r\n        pm1_na: getPMNA(1),\r\n        pm2_na: getPMNA(2),\r\n        pm3_na: getPMNA(3),\r\n        pm4_na: getPMNA(4),\r\n      });\r\n    } else {\r\n      setEquipmentForm(emptyEquipmentForm);\r\n    }\r\n\r\n    setShowEquipmentForm(true);\r\n  }\r\n\r\n  function updateEquipmentField(\r\n    field: keyof EquipmentForm,\r\n    value: string\r\n  ) {\r\n    setEquipmentForm((current) => ({\r\n      ...current,\r\n      [field]: value,\r\n    }));\r\n  }\r\n\r\n  async function saveEquipment() {\r\n    if (\r\n      !equipmentForm.sno ||\r\n      !equipmentForm.department ||\r\n      !equipmentForm.inventory_no ||\r\n      !equipmentForm.equipment_name\r\n    ) {\r\n      alert(\r\n        \"S.NO, Department, Inventory No and Equipment are required.\"\r\n      );\r\n      return;\r\n    }\r\n\r\n    const response = await fetch(\"/api/equipment\", {\r\n      method: editingEquipment ? \"PATCH\" : \"POST\",\r\n      headers: {\r\n        \"Content-Type\": \"application/json\",\r\n      },\r\n      body: JSON.stringify(\r\n        editingEquipment\r\n          ? {\r\n              ...equipmentForm,\r\n              id: editingEquipment.id,\r\n              pm_dates: {\r\n                1: equipmentForm.pm1_na ? null : equipmentForm.pm1_date,\r\n                2: equipmentForm.pm2_na ? null : equipmentForm.pm2_date,\r\n                3: equipmentForm.pm3_na ? null : equipmentForm.pm3_date,\r\n                4: equipmentForm.pm4_na ? null : equipmentForm.pm4_date,\r\n              },\r\n            }\r\n          : {\r\n              ...equipmentForm,\r\n              pm_dates: {\r\n                1: equipmentForm.pm1_na ? null : equipmentForm.pm1_date,\r\n                2: equipmentForm.pm2_na ? null : equipmentForm.pm2_date,\r\n                3: equipmentForm.pm3_na ? null : equipmentForm.pm3_date,\r\n                4: equipmentForm.pm4_na ? null : equipmentForm.pm4_date,\r\n              },\r\n            }\r\n      ),\r\n    });\r\n\r\n    const data = await response.json();\r\n\r\n    if (!response.ok) {\r\n      alert(data.error ?? \"Could not save equipment.\");\r\n      return;\r\n    }\r\n\r\n    setShowEquipmentForm(false);\r\n    setEditingEquipment(null);\r\n    await load();\r\n  }\r\n\r\n  async function deleteEquipment(id: string) {\r\n    if (\r\n      !window.confirm(\r\n        \"Delete this equipment and its PM schedules?\"\r\n      )\r\n    ) {\r\n      return;\r\n    }\r\n\r\n    const response = await fetch(\"/api/equipment\", {\r\n      method: \"DELETE\",\r\n      headers: {\r\n        \"Content-Type\": \"application/json\",\r\n      },\r\n      body: JSON.stringify({ id }),\r\n    });\r\n\r\n    const data = await response.json();\r\n\r\n    if (!response.ok) {\r\n      alert(data.error ?? \"Could not delete equipment.\");\r\n      return;\r\n    }\r\n\r\n    await load();\r\n  }\r\n\r\n  function openPMDateEditor(pm: PMSchedule) {\r\n    setEditingPM(pm);\r\n    setPmDate(pm.scheduled_date ?? \"\");\r\n  }\r\n\r\n  async function savePMDate() {\r\n    if (!editingPM || !pmDate) return;\r\n\r\n    const response = await fetch(`/api/pm/${editingPM.id}`, {\r\n      method: \"PATCH\",\r\n      headers: {\r\n        \"Content-Type\": \"application/json\",\r\n      },\r\n      body: JSON.stringify({\r\n        scheduled_date: pmDate,\r\n      }),\r\n    });\r\n\r\n    const data = await response.json();\r\n\r\n    if (!response.ok) {\r\n      alert(data.error ?? \"Could not update PM date.\");\r\n      return;\r\n    }\r\n\r\n    setEditingPM(null);\r\n    setPmDate(\"\");\r\n    await load();\r\n  }\r\n\r\n  /*\r\n   * EXCEL EXPORT\r\n   */\r\n  function exportExcel() {\r\n    const rows: Record<string, string | number>[] = [];\r\n\r\n    filtered.forEach((e) => {\r\n      const getPM = (number: number) =>\r\n        e.pm_schedules?.find((pm) => pm.pm_no === number);\r\n\r\n      const pm1 = getPM(1);\r\n      const pm2 = getPM(2);\r\n      const pm3 = getPM(3);\r\n      const pm4 = getPM(4);\r\n\r\n      rows.push({\r\n        \"S.NO\": e.sno,\r\n        Department: e.department,\r\n        \"Inventory No\": e.inventory_no,\r\n        Location: e.location ?? \"\",\r\n        Equipment: e.equipment_name,\r\n        Model: e.model ?? \"\",\r\n        \"Serial No\": e.serial_no ?? \"\",\r\n        Make: e.make ?? \"\",\r\n        Campus: e.campus ?? \"\",\r\n        Contract: e.contract ?? \"\",\r\n\r\n        \"PM 1 Date\": pm1?.scheduled_date ?? \"\",\r\n        \"PM 1 Status\": pm1 ? getPMStatus(pm1) : \"\",\r\n        \"PM 1 Completed\": pm1?.completed_date ?? \"\",\r\n\r\n        \"PM 2 Date\": pm2?.scheduled_date ?? \"\",\r\n        \"PM 2 Status\": pm2 ? getPMStatus(pm2) : \"\",\r\n        \"PM 2 Completed\": pm2?.completed_date ?? \"\",\r\n\r\n        \"PM 3 Date\": pm3?.scheduled_date ?? \"\",\r\n        \"PM 3 Status\": pm3 ? getPMStatus(pm3) : \"\",\r\n        \"PM 3 Completed\": pm3?.completed_date ?? \"\",\r\n\r\n        \"PM 4 Date\": pm4?.scheduled_date ?? \"\",\r\n        \"PM 4 Status\": pm4 ? getPMStatus(pm4) : \"\",\r\n        \"PM 4 Completed\": pm4?.completed_date ?? \"\",\r\n      });\r\n    });\r\n\r\n    const worksheet = XLSX.utils.json_to_sheet(rows);\r\n\r\n    worksheet[\"!cols\"] = [\r\n      { wch: 8 },\r\n      { wch: 18 },\r\n      { wch: 18 },\r\n      { wch: 18 },\r\n      { wch: 28 },\r\n      { wch: 18 },\r\n      { wch: 20 },\r\n      { wch: 18 },\r\n      { wch: 18 },\r\n      { wch: 18 },\r\n      { wch: 15 },\r\n      { wch: 15 },\r\n      { wch: 18 },\r\n      { wch: 15 },\r\n      { wch: 15 },\r\n      { wch: 18 },\r\n      { wch: 15 },\r\n      { wch: 15 },\r\n      { wch: 18 },\r\n      { wch: 15 },\r\n      { wch: 15 },\r\n      { wch: 18 },\r\n    ];\r\n\r\n    const workbook = XLSX.utils.book_new();\r\n\r\n    XLSX.utils.book_append_sheet(\r\n      workbook,\r\n      worksheet,\r\n      \"PM Schedule\"\r\n    );\r\n\r\n    XLSX.writeFile(\r\n      workbook,\r\n      `preventive-maintenance-${new Date()\r\n        .toISOString()\r\n        .slice(0, 10)}.xlsx`\r\n    );\r\n  }\r\n\r\n  /*\r\n   * EXCEL IMPORT\r\n   */\r\n  async function importExcel(\r\n    event: React.ChangeEvent<HTMLInputElement>\r\n  ) {\r\n    const file = event.target.files?.[0];\r\n\r\n    event.target.value = \"\";\r\n\r\n    if (!file) return;\r\n\r\n    setImporting(true);\r\n\r\n    try {\r\n      const buffer = await file.arrayBuffer();\r\n\r\n      const workbook = XLSX.read(buffer, {\r\n        type: \"array\",\r\n        cellDates: true,\r\n      });\r\n\r\n      const firstSheet = workbook.SheetNames[0];\r\n\r\n      if (!firstSheet) {\r\n        throw new Error(\"Excel file does not contain a worksheet.\");\r\n      }\r\n\r\n      const worksheet = workbook.Sheets[firstSheet];\r\n\r\n      const rows = XLSX.utils.sheet_to_json<\r\n        Record<string, unknown>\r\n      >(worksheet, {\r\n        defval: \"\",\r\n      });\r\n\r\n      if (!rows.length) {\r\n        throw new Error(\"The Excel sheet is empty.\");\r\n      }\r\n\r\n      let imported = 0;\r\n\r\n      for (const row of rows) {\r\n        const snoValue = excelValue(row, [\r\n          \"S.NO\",\r\n          \"S NO\",\r\n          \"S_NO\",\r\n          \"Sno\",\r\n        ]);\r\n\r\n        const department = String(\r\n          excelValue(row, [\"Department\"])\r\n        ).trim();\r\n\r\n        const inventoryNo = String(\r\n          excelValue(row, [\r\n            \"Inventory No\",\r\n            \"Inventory\",\r\n            \"Inventory Number\",\r\n          ])\r\n        ).trim();\r\n\r\n        const equipmentName = String(\r\n          excelValue(row, [\r\n            \"Equipment\",\r\n            \"Equipment Name\",\r\n          ])\r\n        ).trim();\r\n\r\n        if (\r\n          !snoValue ||\r\n          !department ||\r\n          !inventoryNo ||\r\n          !equipmentName\r\n        ) {\r\n          console.warn(\r\n            \"Skipping incomplete Excel row:\",\r\n            row\r\n          );\r\n          continue;\r\n        }\r\n\r\n        const sno = Number(snoValue);\r\n\r\n        if (!Number.isFinite(sno)) {\r\n          console.warn(\r\n            \"Skipping row with invalid S.NO:\",\r\n            row\r\n          );\r\n          continue;\r\n        }\r\n\r\n        const pm1 = cleanDate(\r\n          excelValue(row, [\r\n            \"PM 1 Date\",\r\n            \"PM1 Date\",\r\n            \"PM 1\",\r\n            \"PM1\",\r\n          ])\r\n        );\r\n\r\n        const pm2 = cleanDate(\r\n          excelValue(row, [\r\n            \"PM 2 Date\",\r\n            \"PM2 Date\",\r\n            \"PM 2\",\r\n            \"PM2\",\r\n          ])\r\n        );\r\n\r\n        const pm3 = cleanDate(\r\n          excelValue(row, [\r\n            \"PM 3 Date\",\r\n            \"PM3 Date\",\r\n            \"PM 3\",\r\n            \"PM3\",\r\n          ])\r\n        );\r\n\r\n        const pm4 = cleanDate(\r\n          excelValue(row, [\r\n            \"PM 4 Date\",\r\n            \"PM4 Date\",\r\n            \"PM 4\",\r\n            \"PM4\",\r\n          ])\r\n        );\r\n\r\n        const payload = {\r\n          sno,\r\n          department,\r\n          inventory_no: inventoryNo,\r\n          location: String(\r\n            excelValue(row, [\"Location\"])\r\n          ).trim(),\r\n          equipment_name: equipmentName,\r\n          model: String(\r\n            excelValue(row, [\"Model\"])\r\n          ).trim(),\r\n          serial_no: String(\r\n            excelValue(row, [\r\n              \"Serial No\",\r\n              \"Serial Number\",\r\n              \"Serial\",\r\n            ])\r\n          ).trim(),\r\n          make: String(\r\n            excelValue(row, [\"Make\"])\r\n          ).trim(),\r\n          campus: String(\r\n            excelValue(row, [\"Campus\"])\r\n          ).trim(),\r\n          contract: String(\r\n            excelValue(row, [\"Contract\"])\r\n          ).trim(),\r\n          pm_dates: {\r\n            1: pm1,\r\n            2: pm2,\r\n            3: pm3,\r\n            4: pm4,\r\n          },\r\n        };\r\n\r\n        const response = await fetch(\r\n          \"/api/equipment\",\r\n          {\r\n            method: \"POST\",\r\n            headers: {\r\n              \"Content-Type\": \"application/json\",\r\n            },\r\n            body: JSON.stringify(payload),\r\n          }\r\n        );\r\n\r\n        const data = await response.json();\r\n\r\n        if (!response.ok) {\r\n          throw new Error(\r\n            data.error ??\r\n              `Could not import inventory ${inventoryNo}.`\r\n          );\r\n        }\r\n\r\n        imported++;\r\n      }\r\n\r\n      await load();\r\n\r\n      alert(\r\n        `Excel import completed.\\n\\n${imported} equipment records imported.`\r\n      );\r\n    } catch (error) {\r\n      console.error(error);\r\n\r\n      alert(\r\n        error instanceof Error\r\n          ? error.message\r\n          : \"Could not import Excel file.\"\r\n      );\r\n    } finally {\r\n      setImporting(false);\r\n    }\r\n  }\r\n\r\n  function reset() {\r\n    setSearch(\"\");\r\n    setEquipmentFilter(\"All\");\r\n    setSectionFilter(\"All\");\r\n    setCampus(\"All\");\r\n    setDepartment(\"All\");\r\n    setContract(\"All\");\r\n    setStatus(\"Any status\");\r\n    setPmNumber(\"All\");\r\n  }\r\n\r\n  /*\r\n   * CSV EXPORT - KEPT\r\n   */\r\n  function exportCSV() {\r\n    const rows: string[][] = [\r\n      [\r\n        \"S.NO\",\r\n        \"Department\",\r\n        \"Inventory No\",\r\n        \"Location\",\r\n        \"Equipment\",\r\n        \"Model\",\r\n        \"Serial No\",\r\n        \"Make\",\r\n        \"Campus\",\r\n        \"Contract\",\r\n        \"PM No\",\r\n        \"Scheduled Date\",\r\n        \"Status\",\r\n        \"PM Done\",\r\n      ],\r\n    ];\r\n\r\n    filtered.forEach((e) =>\r\n      (e.pm_schedules ?? [])\r\n        .sort((a, b) => a.pm_no - b.pm_no)\r\n        .forEach((pm) =>\r\n          rows.push([\r\n            String(e.sno),\r\n            e.department,\r\n            e.inventory_no,\r\n            e.location ?? \"\",\r\n            e.equipment_name,\r\n            e.model ?? \"\",\r\n            e.serial_no ?? \"\",\r\n            e.make ?? \"\",\r\n            e.campus ?? \"\",\r\n            e.contract ?? \"\",\r\n            String(pm.pm_no),\r\n            pm.scheduled_date ?? \"N/A\",\r\n            getPMStatus(pm),\r\n            pm.completed_date ?? \"\",\r\n          ])\r\n        )\r\n    );\r\n\r\n    const csv = rows\r\n      .map((row) =>\r\n        row\r\n          .map((v) => `\"${v.replaceAll('\"', '\"\"')}\"`)\r\n          .join(\",\")\r\n      )\r\n      .join(\"\\n\");\r\n\r\n    const blob = new Blob([csv], {\r\n      type: \"text/csv;charset=utf-8\",\r\n    });\r\n\r\n    const a = document.createElement(\"a\");\r\n\r\n    a.href = URL.createObjectURL(blob);\r\n    a.download = \"preventive-maintenance.csv\";\r\n    a.click();\r\n\r\n    URL.revokeObjectURL(a.href);\r\n  }\r\n\r\n  async function handleLogin(e: FormEvent) {\r\n    e.preventDefault();\r\n\r\n    setError(\"\");\r\n    setLoading(true);\r\n\r\n    try {\r\n      let authEmail = \"\";\r\n\r\n      if (loginType === \"email\") {\r\n        if (!email.trim()) {\r\n          setError(\"Please enter your email.\");\r\n          setLoading(false);\r\n          return;\r\n        }\r\n\r\n        authEmail = email.trim();\r\n      } else {\r\n        if (!loginId.trim()) {\r\n          setError(\"Please enter your Login ID.\");\r\n          setLoading(false);\r\n          return;\r\n        }\r\n\r\n        const response = await fetch(\"/api/auth/login-id\", {\r\n          method: \"POST\",\r\n          headers: {\r\n            \"Content-Type\": \"application/json\",\r\n          },\r\n          body: JSON.stringify({\r\n            loginId: loginId.trim(),\r\n          }),\r\n        });\r\n\r\n        const result = await response.json();\r\n\r\n        if (!response.ok) {\r\n          setError(result.error || \"Login ID not found.\");\r\n          setLoading(false);\r\n          return;\r\n        }\r\n\r\n        authEmail = result.email;\r\n      }\r\n\r\n      if (!password) {\r\n        setError(\"Please enter your password.\");\r\n        setLoading(false);\r\n        return;\r\n      }\r\n\r\n      const { error: signInError } =\r\n        await supabase.auth.signInWithPassword({\r\n          email: authEmail,\r\n          password,\r\n        });\r\n\r\n      if (signInError) {\r\n        setError(\"Invalid credentials.\");\r\n        setLoading(false);\r\n        return;\r\n      }\r\n\r\n      router.replace(\"/\");\r\n      router.refresh();\r\n    } catch {\r\n      setError(\"Unable to sign in. Please try again.\");\r\n    }\r\n\r\n    setLoading(false);\r\n  }\r\n\r\n  async function signUp() {\r\n    setAuthMessage(\"\");\r\n\r\n    const { error } =\r\n      await supabase.auth.signUp({\r\n        email,\r\n        password,\r\n      });\r\n\r\n    setAuthMessage(\r\n      error\r\n        ? error.message\r\n        : \"Account created. Check email if confirmation is enabled.\"\r\n    );\r\n  }\r\n\r\n  async function resetPassword() {\r\n    if (!email) {\r\n      alert(\"Please enter your email first.\");\r\n      return;\r\n    }\r\n\r\n    const { error } =\r\n      await supabase.auth.resetPasswordForEmail(email, {\r\n        redirectTo: `${window.location.origin}/reset-password`,\r\n      });\r\n\r\n    if (error) {\r\n      alert(error.message);\r\n    } else {\r\n      alert(\r\n        \"Password reset email sent. Check your email.\"\r\n      );\r\n    }\r\n  }\r\n\r\n  async function signOut() {\r\n    await supabase.auth.signOut();\r\n    await load();\r\n    await loadUserRole();\r\n  }\r\n\r\n  return (\r\n    <main className=\"page dashboard\">\r\n      <header className=\"topbar dashboard-header\">\r\n        <div className=\"brand\">\r\n          <div className=\"logo\">\r\n            <Wrench size={23} />\r\n          </div>\r\n\r\n          <div>\r\n            <div className=\"title\">\r\n              Preventive Maintenance Dashboard\r\n            </div>\r\n\r\n            <div className=\"subtitle\">\r\n              Auto-calculated PM status ·{\" \"}\r\n              <span\r\n                className={\r\n                  connected\r\n                    ? \"connection ok\"\r\n                    : \"connection\"\r\n                }\r\n              >\r\n                {connected\r\n                  ? \" Supabase connected\"\r\n                  : \" Database unavailable\"}\r\n              </span>\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n        <div className=\"actions\">\r\n          {(userRole === \"SUPER_ADMIN\" ||\r\n            userRole === \"SUPER_VIEWER\") ? (\r\n            <div className=\"header-section-selector\">\r\n              <Layers size={18} />\r\n\r\n              <span>Section:</span>\r\n\r\n              <select\r\n                value={sectionFilter}\r\n                onChange={(e) => setSectionFilter(e.target.value)}\r\n              >\r\n                <option value=\"All\">All Sections</option>\r\n\r\n                <option value=\"HIGH_END_RADIOLOGY\">\r\n                  High-End & Radiology\r\n                </option>\r\n\r\n                <option value=\"LIFE_SUPPORT\">\r\n                  Life Support and Surgical\r\n                </option>\r\n\r\n                <option value=\"GENERAL_MONITORING\">\r\n                  General Monitoring\r\n                </option>\r\n              </select>\r\n            </div>\r\n          ) : (\r\n            <div className=\"header-section-name\">\r\n              <Layers size={18} />\r\n\r\n              <span>\r\n                {userSection\r\n                  ? getSectionLabel(userSection)\r\n                  : \"Section\"}\r\n              </span>\r\n            </div>\r\n          )}\r\n\r\n          <button className=\"btn\">\r\n            <CalendarDays size={15} />\r\n            As of <b>{fmtDate(new Date())}</b>\r\n          </button>\r\n\r\n          <button\r\n            className=\"btn\"\r\n            onClick={exportExcel}\r\n            title=\"Export Excel\"\r\n          >\r\n            <FileSpreadsheet size={15} />\r\n            Excel Export\r\n          </button>\r\n\r\n          <button\r\n            className=\"btn\"\r\n            onClick={exportCSV}\r\n          >\r\n            <Download size={15} />\r\n            CSV\r\n          </button>\r\n\r\n          <button\r\n            className=\"btn\"\r\n            onClick={() => load()}\r\n          >\r\n            <RefreshCw size={15} />\r\n            Refresh\r\n          </button>\r\n\r\n          <button\r\n            className=\"btn\"\r\n            onClick={reset}\r\n          >\r\n            <RotateCcw size={15} />\r\n            Reset\r\n          </button>\r\n\r\n          {isSuperAdmin && (\r\n            <button\r\n              className=\"secondary-button\"\r\n              onClick={() =>\r\n                setShowUserManagement((value) => !value)\r\n              }\r\n            >\r\n              User Management\r\n            </button>\r\n          )}\r\n\r\n          {userEmail ? (\r\n            <button\r\n              className=\"btn\"\r\n              onClick={signOut}\r\n            >\r\n              {userEmail} · Sign out\r\n            </button>\r\n          ) : (\r\n            <button\r\n              className=\"btn primary\"\r\n              onClick={() => setAuthOpen(true)}\r\n            >\r\n              <LogIn size={15} />\r\n              Sign in\r\n            </button>\r\n          )}\r\n        </div>\r\n      </header>\r\n\r\n      <div className=\"dashboard-content\">\r\n      <section className=\"filter-bar dashboard-filter-bar\">\r\n        <div className=\"filter-field equipment-search\">\r\n          <label>Equipment</label>\r\n\r\n          <div className=\"filter-search-box\">\r\n            <Search size={16} />\r\n\r\n            <input\r\n              type=\"text\"\r\n              value={search}\r\n              onChange={(e) => setSearch(e.target.value)}\r\n              placeholder=\"Search equipment, inventory, serial no...\"\r\n            />\r\n\r\n            {search && (\r\n              <button\r\n                type=\"button\"\r\n                onClick={() => setSearch(\"\")}\r\n                aria-label=\"Clear equipment search\"\r\n              >\r\n                <X size={14} />\r\n              </button>\r\n            )}\r\n          </div>\r\n        </div>\r\n\r\n        <div className=\"filter-field equipment-select\">\r\n          <label>Equipment</label>\r\n\r\n          <select\r\n            value={equipmentFilter}\r\n            onChange={(e) => setEquipmentFilter(e.target.value)}\r\n          >\r\n            <option value=\"All\">All Equipment</option>\r\n\r\n            {equipmentNames.map((name) => (\r\n                <option key={name} value={name}>\r\n                  {name}\r\n                </option>\r\n              ))}\r\n          </select>\r\n        </div>\r\n\r\n        {(userRole === \"SUPER_ADMIN\" ||\r\n          userRole === \"SUPER_VIEWER\") && (\r\n          <div className=\"filter-field section-filter\">\r\n            <label>Section</label>\r\n\r\n            <select\r\n              value={sectionFilter}\r\n              onChange={(e) => setSectionFilter(e.target.value)}\r\n            >\r\n              <option value=\"All\">All Sections</option>\r\n              <option value=\"HIGH_END_RADIOLOGY\">\r\n                High-End & Radiology\r\n              </option>\r\n              <option value=\"LIFE_SUPPORT\">\r\n                Life Support and Surgical\r\n              </option>\r\n              <option value=\"GENERAL_MONITORING\">\r\n                General Monitoring\r\n              </option>\r\n            </select>\r\n          </div>\r\n        )}\r\n\r\n        <div className=\"filter-field\">\r\n          <label>Campus</label>\r\n          <select value={campus} onChange={(e) => setCampus(e.target.value)}>\r\n            <option value=\"All\">All Campuses</option>\r\n            {campuses.map((item) => (\r\n              <option key={item} value={item}>\r\n                {item}\r\n              </option>\r\n            ))}\r\n          </select>\r\n        </div>\r\n\r\n        <div className=\"filter-field\">\r\n          <label>Department</label>\r\n          <select value={department} onChange={(e) => setDepartment(e.target.value)}>\r\n            <option value=\"All\">All Departments</option>\r\n            {departments.map((item) => (\r\n              <option key={item} value={item}>\r\n                {item}\r\n              </option>\r\n            ))}\r\n          </select>\r\n        </div>\r\n\r\n        <div className=\"filter-field\">\r\n          <label>Contract</label>\r\n          <select value={contract} onChange={(e) => setContract(e.target.value)}>\r\n            <option value=\"All\">All Contracts</option>\r\n            {contracts.map((item) => (\r\n              <option key={item} value={item}>\r\n                {item}\r\n              </option>\r\n            ))}\r\n          </select>\r\n        </div>\r\n\r\n        <div className=\"filter-field\">\r\n          <label>PM</label>\r\n          <select value={pmNumber} onChange={(e) => setPmNumber(e.target.value)}>\r\n            <option value=\"All\">All PMs</option>\r\n            <option value=\"1\">PM 1</option>\r\n            <option value=\"2\">PM 2</option>\r\n            <option value=\"3\">PM 3</option>\r\n            <option value=\"4\">PM 4</option>\r\n          </select>\r\n        </div>\r\n\r\n        <div className=\"filter-field\">\r\n          <label>Status</label>\r\n          <select value={status} onChange={(e) => setStatus(e.target.value)}>\r\n            <option value=\"Any status\">Any Status</option>\r\n            <option value=\"Done\">Done</option>\r\n            <option value=\"Pending\">Pending</option>\r\n            <option value=\"Overdue\">Overdue</option>\r\n            <option value=\"Scheduled\">Scheduled</option>\r\n          </select>\r\n        </div>\r\n\r\n        <button\r\n          type=\"button\"\r\n          className=\"reset-filters\"\r\n          onClick={reset}\r\n        >\r\n          Reset\r\n        </button>\r\n      </section>\r\n\r\n      {isSuperAdmin && showUserManagement && (\r\n        <section className=\"user-management-card\">\r\n          <div className=\"section-header\">\r\n            <div>\r\n              <h2>User Management</h2>\r\n              <p>\r\n                Create section-based Login ID and password accounts\r\n              </p>\r\n            </div>\r\n          </div>\r\n\r\n          <div className=\"user-form-grid\">\r\n            <div className=\"form-field\">\r\n              <label>Login ID</label>\r\n              <input\r\n                type=\"text\"\r\n                value={newUser.login_id}\r\n                onChange={(e) =>\r\n                  setNewUser({\r\n                    ...newUser,\r\n                    login_id: e.target.value,\r\n                  })\r\n                }\r\n                placeholder=\"Enter Login ID\"\r\n              />\r\n            </div>\r\n\r\n            <div className=\"form-field\">\r\n              <label>Email</label>\r\n              <input\r\n                type=\"email\"\r\n                value={newUser.email}\r\n                onChange={(e) =>\r\n                  setNewUser({\r\n                    ...newUser,\r\n                    email: e.target.value,\r\n                  })\r\n                }\r\n                placeholder=\"Enter email\"\r\n              />\r\n            </div>\r\n\r\n            <div className=\"form-field\">\r\n              <label>Password</label>\r\n              <input\r\n                type=\"password\"\r\n                value={newUser.password}\r\n                onChange={(e) =>\r\n                  setNewUser({\r\n                    ...newUser,\r\n                    password: e.target.value,\r\n                  })\r\n                }\r\n                placeholder=\"Enter password\"\r\n              />\r\n            </div>\r\n\r\n            <div className=\"form-field\">\r\n              <label>Role</label>\r\n              <select\r\n                value={newUser.role}\r\n                onChange={(e) => {\r\n                  const role = e.target.value;\r\n\r\n                  setNewUser({\r\n                    ...newUser,\r\n                    role,\r\n                    section:\r\n                      role === \"SUPER_ADMIN\" ||\r\n                      role === \"SUPER_VIEWER\"\r\n                        ? \"None\"\r\n                        : \"HIGH_END_RADIOLOGY\",\r\n                  });\r\n                }}\r\n              >\r\n                <option value=\"technician\">Technician</option>\r\n                <option value=\"section_admin\">Section Admin</option>\r\n                <option value=\"SUPER_VIEWER\">Super Viewer</option>\r\n                <option value=\"SUPER_ADMIN\">Super Admin</option>\r\n              </select>\r\n            </div>\r\n\r\n            <div className=\"form-field\">\r\n              <label>Section</label>\r\n              <select\r\n                value={newUser.section}\r\n                disabled={\r\n                  newUser.role === \"SUPER_ADMIN\" ||\r\n                  newUser.role === \"SUPER_VIEWER\"\r\n                }\r\n                onChange={(e) =>\r\n                  setNewUser({\r\n                    ...newUser,\r\n                    section: e.target.value,\r\n                  })\r\n                }\r\n              >\r\n                <option value=\"None\">No Section</option>\r\n                <option value=\"HIGH_END_RADIOLOGY\">\r\n                  High-End & Radiology\r\n                </option>\r\n                <option value=\"LIFE_SUPPORT\">\r\n                  Life Support and Surgical\r\n                </option>\r\n                <option value=\"GENERAL_MONITORING\">\r\n                  General Monitoring\r\n                </option>\r\n              </select>\r\n            </div>\r\n          </div>\r\n\r\n          <div className=\"user-management-actions\">\r\n            <button\r\n              className=\"primary-button\"\r\n              onClick={createUser}\r\n              disabled={creatingUser}\r\n            >\r\n              {creatingUser ? \"Creating...\" : \"Create User\"}\r\n            </button>\r\n          </div>\r\n\r\n          {userMessage && (\r\n            <div className=\"user-message\">{userMessage}</div>\r\n          )}\r\n        </section>\r\n      )}\r\n\r\n      <section className=\"kpi-grid stats-grid\">\r\n        <Stat label=\"TOTAL EQUIPMENT\" value={filtered.length} hint=\"Equipment assets\" icon={<MonitorCog />} />\r\n        <Stat label=\"ACTIVE PMs\" value={filteredCounts.total} hint=\"N/A excluded\" icon={<ClipboardCheck />} />\r\n        <Stat label=\"PM DONE\" value={filteredCounts.Done} hint=\"Completed PMs\" icon={<CheckCircle2 />} />\r\n        <div className=\"clickable-stat\" onClick={() => setShowDueSoon(true)}>\r\n          <Stat label=\"PM DUE SOON\" value={filteredCounts.Pending} hint=\"Within next 30 days\" warning icon={<Clock3 />} />\r\n        </div>\r\n        <div className=\"clickable-stat\" onClick={() => setShowOverdue(true)}>\r\n          <Stat label=\"OVERDUE\" value={filteredCounts.Overdue} hint=\"Requires attention\" danger icon={<AlertTriangle />} />\r\n        </div>\r\n        <Stat label=\"Compliance (Overall)\" value={`${overallCompliance}%`} hint={`${complianceDone} / ${complianceTotal} active PMs`} icon={<ShieldCheck />} progress={overallCompliance} />\r\n        <Stat\r\n          label=\"Compliance (This Month)\"\r\n          value={`${monthlyCompliance.compliance}%`}\r\n          hint={`${monthlyCompliance.done} / ${monthlyCompliance.total} PMs`}\r\n          icon={<CheckCircle2 />}\r\n          progress={monthlyCompliance.compliance}\r\n        />\r\n      </section>\r\n\r\n      <section className=\"analytics-section\">\r\n        <div className=\"analytics-grid-four\">\r\n          <div className=\"dashboard-card chart-card\">\r\n            <ChartHeading title=\"PM Status Distribution\" subtitle=\"N/A excluded from calculation\" icon={<PieChart size={21} />} />\r\n            <div className=\"chart-box pie-box\">\r\n              <ResponsiveContainer width=\"100%\" height={270}>\r\n                <RechartsPieChart>\r\n                  <Pie data={pmStatusData} dataKey=\"value\" nameKey=\"name\" cx=\"50%\" cy=\"50%\" innerRadius={65} outerRadius={100} paddingAngle={3}>\r\n                    {pmStatusData.map((entry, index) => <Cell key={`pm-status-${index}`} fill={[\"#16a34a\", \"#f59e0b\", \"#dc2626\", \"#6366f1\"][index]} />)}\r\n                  </Pie>\r\n                  <Tooltip />\r\n                  <Legend verticalAlign=\"bottom\" />\r\n                </RechartsPieChart>\r\n              </ResponsiveContainer>\r\n            </div>\r\n          </div>\r\n\r\n          <div className=\"dashboard-card chart-card\">\r\n            <ChartHeading title=\"PM Status by Campus\" subtitle=\"Active PMs only\" icon={<Building2 size={21} />} />\r\n            <div className=\"chart-box\">\r\n              <ResponsiveContainer width=\"100%\" height={270}>\r\n                <BarChart data={campusPMData} margin={{ top: 5, right: 8, left: -8, bottom: 5 }}><CartesianGrid strokeDasharray=\"3 3\" /><XAxis dataKey=\"campus\" tick={{ fontSize: 11 }} /><YAxis allowDecimals={false} /><Tooltip /><Legend /><Bar dataKey=\"Done\" stackId=\"pm\" name=\"Done\" fill=\"#16a34a\" /><Bar dataKey=\"Due Soon\" stackId=\"pm\" name=\"Due Soon\" fill=\"#f59e0b\" /><Bar dataKey=\"Overdue\" stackId=\"pm\" name=\"Overdue\" fill=\"#dc2626\" /><Bar dataKey=\"Scheduled\" stackId=\"pm\" name=\"Scheduled\" fill=\"#6366f1\" /></BarChart>\r\n              </ResponsiveContainer>\r\n            </div>\r\n          </div>\r\n\r\n          <div className=\"dashboard-card chart-card\">\r\n            <ChartHeading title=\"Department PM Status\" subtitle=\"Current filtered equipment\" icon={<Building2 size={21} />} />\r\n            <div className=\"chart-area department-chart\">\r\n              <ResponsiveContainer width=\"100%\" height={270}>\r\n                <BarChart data={departmentPMData} margin={{ top: 8, right: 5, left: -12, bottom: 5 }}><CartesianGrid strokeDasharray=\"3 3\" vertical={false} /><XAxis dataKey=\"department\" tick={{ fontSize: 8 }} angle={-20} textAnchor=\"end\" height={45} interval={0} /><YAxis allowDecimals={false} tick={{ fontSize: 9 }} /><Tooltip /><Legend verticalAlign=\"bottom\" height={25} /><Bar dataKey=\"Done\" stackId=\"status\" name=\"Done\" fill=\"#16a34a\" radius={[0, 0, 0, 0]} /><Bar dataKey=\"Due Soon\" stackId=\"status\" name=\"Due Soon\" fill=\"#f59e0b\" /><Bar dataKey=\"Overdue\" stackId=\"status\" name=\"Overdue\" fill=\"#dc2626\" /><Bar dataKey=\"Scheduled\" stackId=\"status\" name=\"Scheduled\" fill=\"#6366f1\" radius={[3, 3, 0, 0]} /></BarChart>\r\n              </ResponsiveContainer>\r\n            </div>\r\n          </div>\r\n\r\n          <div className=\"dashboard-card chart-card\">\r\n            <ChartHeading title=\"Compliance by Campus\" subtitle=\"Done ÷ active PMs\" icon={<ShieldCheck size={21} />} />\r\n            <div className=\"chart-box\">\r\n              <ResponsiveContainer width=\"100%\" height={270}>\r\n                <BarChart data={campusComplianceData} margin={{ top: 8, right: 8, left: -8, bottom: 5 }}><CartesianGrid strokeDasharray=\"3 3\" /><XAxis dataKey=\"campus\" tick={{ fontSize: 11 }} /><YAxis domain={[0, 100]} tickFormatter={(value) => `${value}%`} /><Tooltip formatter={(value) => [`${value}%`, \"Compliance\"]} /><Bar dataKey=\"compliance\" name=\"Compliance\" fill=\"#2563eb\" /></BarChart>\r\n              </ResponsiveContainer>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </section>\r\n\r\n      <section className=\"workload-row\">\r\n        <WorkloadCard className=\"workload-overdue\" icon={<AlertTriangle size={22} />} label=\"Overdue PMs\" value={filteredCounts.Overdue} hint=\"Requires attention\" onClick={() => setShowOverdue(true)} />\r\n        <WorkloadCard className=\"workload-pending\" icon={<Clock3 size={22} />} label=\"PM Due Soon\" value={filteredCounts.Pending} hint=\"Within next 30 days\" onClick={() => setShowDueSoon(true)} />\r\n        <WorkloadCard className=\"workload-yet\" icon={<ClipboardCheck size={22} />} label=\"PM Yet to be Done\" value={filteredCounts.Pending + filteredCounts.Overdue} hint=\"Pending + Overdue\" onClick={() => setShowDueSoon(true)} />\r\n      </section>\r\n\r\n      {showDueSoon && <StatusPanel title=\"PMs Due Soon\" subtitle=\"Preventive maintenance due within 30 days\" rows={dueSoonRows} status=\"Pending\" onClose={() => setShowDueSoon(false)} updatePM={updatePM} />}\r\n      {showOverdue && <StatusPanel title=\"Overdue PMs\" subtitle=\"Preventive maintenance requiring attention\" rows={overdueRows} status=\"Overdue\" onClose={() => setShowOverdue(false)} updatePM={updatePM} />}\r\n\r\n      <div className=\"legacy-analytics\">\r\n      <section className=\"stats stats-grid\">\r\n        <div className=\"stat stat-card\">\r\n          <h3>Total Equipment</h3>\r\n          <div className=\"value\">{filtered.length}</div>\r\n          <div className=\"hint\">Active assets</div>\r\n        </div>\r\n\r\n        <div className=\"stat stat-card\">\r\n          <h3>PM Done</h3>\r\n          <div className=\"value\">{filteredCounts.Done}</div>\r\n          <div className=\"hint\">Completed PMs</div>\r\n        </div>\r\n\r\n        <div\r\n          className=\"clickable-stat\"\r\n          onClick={() => setShowDueSoon(true)}\r\n        >\r\n          <div className=\"stat stat-card\">\r\n            <h3>PM Due Soon</h3>\r\n            <div className=\"value\">{filteredCounts.Pending}</div>\r\n            <div className=\"hint\">Within next 30 days</div>\r\n          </div>\r\n        </div>\r\n\r\n        <div className=\"stat stat-card\">\r\n          <h3>Overdue</h3>\r\n          <div className=\"value\">{filteredCounts.Overdue}</div>\r\n          <div className=\"hint\">Requires attention</div>\r\n        </div>\r\n\r\n        <div className=\"stat stat-card\">\r\n          <h3>Compliance</h3>\r\n          <div className=\"value\">{compliancePercentage}%</div>\r\n          <div className=\"hint\">PM completion rate</div>\r\n        </div>\r\n      </section>\r\n\r\n      {showDueSoon && (\r\n        <div className=\"due-soon-panel\">\r\n          <div className=\"panel-header\">\r\n            <div>\r\n              <h2>PM Due Soon</h2>\r\n              <p>PMs due within the next 30 days</p>\r\n            </div>\r\n\r\n            <button\r\n              className=\"btn\"\r\n              onClick={() => setShowDueSoon(false)}\r\n            >\r\n              Close\r\n            </button>\r\n          </div>\r\n\r\n          <div className=\"table-wrap due-soon-table\">\r\n            <table>\r\n              <thead>\r\n                <tr>\r\n                  <th>S.No</th>\r\n                  <th>Equipment</th>\r\n                  <th>Inventory No</th>\r\n                  <th>Department</th>\r\n                  <th>Campus</th>\r\n                  <th>PM</th>\r\n                  <th>Due Date</th>\r\n                  <th>Days Remaining</th>\r\n                  <th>Status</th>\r\n                  <th>Action</th>\r\n                </tr>\r\n              </thead>\r\n\r\n              <tbody>\r\n                {filtered\r\n                  .flatMap((equipment) =>\r\n                    (equipment.pm_schedules ?? []).map((pm) => ({\r\n                      equipment,\r\n                      pm,\r\n                    }))\r\n                  )\r\n                  .filter(\r\n                    ({ pm }) =>\r\n                      pm.scheduled_date !== null &&\r\n                      getPMStatus(pm) === \"Pending\"\r\n                  )\r\n                  .sort((a, b) => {\r\n                    return (\r\n                      new Date(`${a.pm.scheduled_date}T00:00:00`).getTime() -\r\n                      new Date(`${b.pm.scheduled_date}T00:00:00`).getTime()\r\n                    );\r\n                  })\r\n                  .map(({ equipment, pm }, index) => {\r\n                    const today = new Date();\r\n                    today.setHours(0, 0, 0, 0);\r\n\r\n                    const dueDate = new Date(\r\n                      `${pm.scheduled_date}T00:00:00`\r\n                    );\r\n\r\n                    const daysRemaining = Math.ceil(\r\n                      (dueDate.getTime() - today.getTime()) /\r\n                        (1000 * 60 * 60 * 24)\r\n                    );\r\n\r\n                    return (\r\n                      <tr key={pm.id}>\r\n                        <td>{index + 1}</td>\r\n\r\n                        <td>\r\n                          <strong>{equipment.equipment_name}</strong>\r\n\r\n                          {equipment.model && (\r\n                            <div className=\"table-subtext\">\r\n                              {equipment.model}\r\n                            </div>\r\n                          )}\r\n                        </td>\r\n\r\n                        <td>{equipment.inventory_no}</td>\r\n                        <td>{equipment.department}</td>\r\n                        <td>{equipment.campus ?? \"N/A\"}</td>\r\n                        <td>PM {pm.pm_no}</td>\r\n                        <td>{fmtDate(pm.scheduled_date)}</td>\r\n\r\n                        <td>\r\n                          <span\r\n                            className={\r\n                              daysRemaining <= 7\r\n                                ? \"days-urgent\"\r\n                                : \"days-normal\"\r\n                            }\r\n                          >\r\n                            {daysRemaining === 0\r\n                              ? \"Due today\"\r\n                              : `${daysRemaining} days`}\r\n                          </span>\r\n                        </td>\r\n\r\n                        <td>\r\n                          <span className=\"status pending\">\r\n                            Pending\r\n                          </span>\r\n                        </td>\r\n\r\n                        <td>\r\n                          {canUpdateThisPM(equipment) && (\r\n                            <button\r\n                              className=\"btn btn-primary\"\r\n                              onClick={() => updatePM(pm, true)}\r\n                            >\r\n                              Mark Done\r\n                            </button>\r\n                          )}\r\n                        </td>\r\n                      </tr>\r\n                    );\r\n                  })}\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n        </div>\r\n      )}\r\n\r\n      <section className=\"panel filters filter-bar\">\r\n        <div className=\"searchbox\">\r\n          <Search size={17} />\r\n\r\n          <input\r\n            value={search}\r\n            onChange={(e) =>\r\n              setSearch(e.target.value)\r\n            }\r\n            placeholder=\"Search by SNO, equipment, serial, location, model, make...\"\r\n          />\r\n        </div>\r\n\r\n        <Select\r\n          value={campus}\r\n          setValue={setCampus}\r\n          options={campuses}\r\n          label=\"Campus\"\r\n        />\r\n\r\n        <Select\r\n          value={department}\r\n          setValue={setDepartment}\r\n          options={departments}\r\n          label=\"Department\"\r\n        />\r\n\r\n        <Select\r\n          value={contract}\r\n          setValue={setContract}\r\n          options={contracts}\r\n          label=\"Contract\"\r\n        />\r\n\r\n        <Select\r\n          value={pmNumber}\r\n          setValue={setPmNumber}\r\n          options={[\"1\", \"2\", \"3\", \"4\"]}\r\n          label=\"PM\"\r\n          any=\"All PMs\"\r\n        />\r\n\r\n        <Select\r\n          value={status}\r\n          setValue={setStatus}\r\n          options={[\r\n            \"Done\",\r\n            \"Overdue\",\r\n            \"Pending\",\r\n            \"Scheduled\",\r\n          ]}\r\n          label=\"Status\"\r\n          any=\"Any status\"\r\n        />\r\n      </section>\r\n\r\n      <section className=\"charts dashboard-grid\">\r\n        <div className=\"panel chart dashboard-card\">\r\n          <h2>PM Status by Campus</h2>\r\n          <p>Across all four PM schedules</p>\r\n\r\n          <div className=\"bararea\">\r\n            {filteredCampuses.map((c) => {\r\n              const pms = filtered\r\n                .filter((e) => e.campus === c)\r\n                .flatMap(\r\n                  (e) => e.pm_schedules ?? []\r\n                )\r\n                .filter(\r\n                  (pm) =>\r\n                    pm.scheduled_date !== null &&\r\n                    (pmNumber === \"All\" ||\r\n                      pm.pm_no === Number(pmNumber))\r\n                );\r\n\r\n              const max = Math.max(\r\n                1,\r\n                ...filteredCampuses.map(\r\n                  (x) =>\r\n                    filtered\r\n                      .filter(\r\n                        (e) => e.campus === x\r\n                      )\r\n                      .flatMap(\r\n                        (e) =>\r\n                          e.pm_schedules ?? []\r\n                      )\r\n                      .filter(\r\n                        (pm) =>\r\n                          pm.scheduled_date !== null &&\r\n                          (pmNumber === \"All\" ||\r\n                            pm.pm_no === Number(pmNumber))\r\n                      ).length\r\n                )\r\n              );\r\n\r\n              return (\r\n                <div\r\n                  className=\"baritem\"\r\n                  key={c}\r\n                >\r\n                  <b>{pms.length}</b>\r\n\r\n                  <div\r\n                    className=\"bar\"\r\n                    style={{\r\n                      height: `${Math.max(\r\n                        8,\r\n                        (pms.length / max) * 150\r\n                      )}px`,\r\n                    }}\r\n                  />\r\n\r\n                  <span>{c}</span>\r\n                </div>\r\n              );\r\n            })}\r\n          </div>\r\n        </div>\r\n\r\n        <div className=\"panel chart dashboard-card\">\r\n          <h2>Overall PM Distribution</h2>\r\n          <p>All scheduled PM dates</p>\r\n\r\n          <div\r\n            className=\"donut\"\r\n            style={{\r\n              background: `conic-gradient(\r\n                #08b77d 0 ${\r\n                  (counts.Done /\r\n                    allPMs.length) *\r\n                    100 || 0\r\n                }%,\r\n                #f59b00 ${\r\n                  (counts.Done /\r\n                    allPMs.length) *\r\n                    100 || 0\r\n                }% ${\r\n                  ((counts.Done +\r\n                    counts.Pending) /\r\n                    allPMs.length) *\r\n                    100 || 0\r\n                }%,\r\n                #f51f50 ${\r\n                  ((counts.Done +\r\n                    counts.Pending) /\r\n                    allPMs.length) *\r\n                    100 || 0\r\n                }% ${\r\n                  ((counts.Done +\r\n                    counts.Pending +\r\n                    counts.Overdue) /\r\n                    allPMs.length) *\r\n                    100 || 0\r\n                }%,\r\n                #94a3b8 ${\r\n                  ((counts.Done +\r\n                    counts.Pending +\r\n                    counts.Overdue) /\r\n                    allPMs.length) *\r\n                    100 || 0\r\n                }% 100%\r\n              )`,\r\n            }}\r\n          >\r\n            <div className=\"donutCenter\">\r\n              <b>{allPMs.length}</b>\r\n              <span>Total PMs</span>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </section>\r\n\r\n      </div>\r\n\r\n      <section className=\"schedule-section panel equipment-table equipment-schedule-card\">\r\n        <div className=\"section-header schedule-header equipment-schedule-header\">\r\n          <div className=\"section-banner\">\r\n            <div>\r\n              <span className=\"section-eyebrow\">\r\n                MAINTENANCE SECTION\r\n              </span>\r\n\r\n              <h2>{getSectionHeading()}</h2>\r\n            </div>\r\n\r\n            <div className=\"section-meta\">\r\n              Preventive Maintenance\r\n            </div>\r\n          </div>\r\n\r\n          <div className=\"schedule-heading\">\r\n            <h2>Equipment PM Schedule</h2>\r\n            <p>\r\n              Complete preventive maintenance schedule for all equipment\r\n            </p>\r\n          </div>\r\n\r\n          <small>\r\n            Phone/tablet: swipe horizontally. No\r\n            equipment or PM data is hidden.\r\n          </small>\r\n\r\n          {canManageEquipment && (\r\n            <div className=\"admin-actions\">\r\n              <button\r\n                type=\"button\"\r\n                className=\"admin-button\"\r\n                onClick={() =>\r\n                  openEquipmentForm()\r\n                }\r\n              >\r\n                <Plus size={18} />\r\n                Add Equipment\r\n              </button>\r\n\r\n              <label className=\"admin-button\">\r\n                <FileSpreadsheet size={18} />\r\n\r\n                {importing\r\n                  ? \"Importing...\"\r\n                  : \"Import Excel\"}\r\n\r\n                <input\r\n                  type=\"file\"\r\n                  accept=\".xlsx,.xls\"\r\n                  hidden\r\n                  disabled={importing}\r\n                  onChange={importExcel}\r\n                />\r\n              </label>\r\n            </div>\r\n          )}\r\n        </div>\r\n\r\n        <div className=\"schedule-search schedule-search-bar\">\r\n          <div className=\"schedule-search-box\">\r\n            <Search size={17} />\r\n            <input\r\n              type=\"text\"\r\n              value={scheduleSearch}\r\n              onChange={(e) => setScheduleSearch(e.target.value)}\r\n              placeholder=\"Search Equipment PM Schedule...\"\r\n            />\r\n            {scheduleSearch && (\r\n              <button\r\n                type=\"button\"\r\n                className=\"schedule-search-clear\"\r\n                onClick={() => setScheduleSearch(\"\")}\r\n                aria-label=\"Clear schedule search\"\r\n              >\r\n                <X size={15} />\r\n              </button>\r\n            )}\r\n          </div>\r\n          <div className=\"schedule-search-info\">\r\n            Showing <strong>{scheduleFiltered.length}</strong> of{\" \"}\r\n            <strong>{filtered.length}</strong> equipment\r\n          </div>\r\n        </div>\r\n\r\n        <div className=\"table-container tablewrap table-wrap equipment-schedule-table\">\r\n          <table>\r\n            <thead>\r\n              <tr>\r\n                <th>S.NO</th>\r\n                {sectionFilter === \"All\" && (\r\n                  <th>SECTION</th>\r\n                )}\r\n                <th>DEPARTMENT</th>\r\n                <th>INVENTORY NO</th>\r\n                <th>LOCATION</th>\r\n                <th>EQUIPMENT</th>\r\n                <th>MODEL</th>\r\n                <th>SERIAL NO</th>\r\n                <th>MAKE</th>\r\n                <th>CAMPUS</th>\r\n                <th>CONTRACT</th>\r\n                <th>PM 1</th>\r\n                <th>PM 2</th>\r\n                <th>PM 3</th>\r\n                <th>PM 4</th>\r\n\r\n                {canManageEquipment && (\r\n                  <th>ACTIONS</th>\r\n                )}\r\n              </tr>\r\n            </thead>\r\n\r\n            <tbody>\r\n              {loading ? (\r\n                <tr>\r\n                  <td\r\n                    colSpan={\r\n                      (canManageEquipment ? 15 : 14) +\r\n                      (sectionFilter === \"All\" ? 1 : 0)\r\n                    }\r\n                    className=\"empty\"\r\n                  >\r\n                    Loading...\r\n                  </td>\r\n                </tr>\r\n              ) : filtered.length === 0 ? (\r\n                <tr>\r\n                  <td\r\n                    colSpan={\r\n                      (canManageEquipment ? 15 : 14) +\r\n                      (sectionFilter === \"All\" ? 1 : 0)\r\n                    }\r\n                    className=\"empty\"\r\n                  >\r\n                    No data found.\r\n                  </td>\r\n                </tr>\r\n              ) : (\r\n                scheduleFiltered.map((e, index) => (\r\n                  <EquipmentRow\r\n                    key={e.id}\r\n                    e={e}\r\n                    index={index}\r\n                    showSection={sectionFilter === \"All\"}\r\n                    canManage={canManageThisEquipment(e)}\r\n                    canUpdate={canUpdateThisPM(e)}\r\n                    updatePM={updatePM}\r\n                    markAll={markAll}\r\n                    openEquipmentForm={\r\n                      openEquipmentForm\r\n                    }\r\n                    deleteEquipment={\r\n                      deleteEquipment\r\n                    }\r\n                    openPMDateEditor={\r\n                      openPMDateEditor\r\n                    }\r\n                  />\r\n                ))\r\n              )}\r\n            </tbody>\r\n          </table>\r\n        </div>\r\n      </section>\r\n\r\n      </div>\r\n\r\n      {showEquipmentForm && (\r\n        <div className=\"overlay\">\r\n          <div className=\"authbox equipment-form\">\r\n            <button\r\n              className=\"close\"\r\n              onClick={() =>\r\n                setShowEquipmentForm(false)\r\n              }\r\n            >\r\n              <X />\r\n            </button>\r\n\r\n            <h2>\r\n              {editingEquipment\r\n                ? \"Edit Equipment\"\r\n                : \"Add Equipment\"}\r\n            </h2>\r\n\r\n            <div className=\"equipment-fields\">\r\n              <input\r\n                value={equipmentForm.sno}\r\n                onChange={(e) =>\r\n                  updateEquipmentField(\r\n                    \"sno\",\r\n                    e.target.value\r\n                  )\r\n                }\r\n                placeholder=\"S.NO\"\r\n                type=\"number\"\r\n              />\r\n\r\n              <input\r\n                value={equipmentForm.department}\r\n                onChange={(e) =>\r\n                  updateEquipmentField(\r\n                    \"department\",\r\n                    e.target.value\r\n                  )\r\n                }\r\n                placeholder=\"Department\"\r\n              />\r\n\r\n              <input\r\n                value={equipmentForm.inventory_no}\r\n                onChange={(e) =>\r\n                  updateEquipmentField(\r\n                    \"inventory_no\",\r\n                    e.target.value\r\n                  )\r\n                }\r\n                placeholder=\"Inventory No\"\r\n              />\r\n\r\n              <input\r\n                value={equipmentForm.location}\r\n                onChange={(e) =>\r\n                  updateEquipmentField(\r\n                    \"location\",\r\n                    e.target.value\r\n                  )\r\n                }\r\n                placeholder=\"Location\"\r\n              />\r\n\r\n              <input\r\n                value={equipmentForm.equipment_name}\r\n                onChange={(e) =>\r\n                  updateEquipmentField(\r\n                    \"equipment_name\",\r\n                    e.target.value\r\n                  )\r\n                }\r\n                placeholder=\"Equipment Name\"\r\n              />\r\n\r\n              <input\r\n                value={equipmentForm.model}\r\n                onChange={(e) =>\r\n                  updateEquipmentField(\r\n                    \"model\",\r\n                    e.target.value\r\n                  )\r\n                }\r\n                placeholder=\"Model\"\r\n              />\r\n\r\n              <input\r\n                value={equipmentForm.serial_no}\r\n                onChange={(e) =>\r\n                  updateEquipmentField(\r\n                    \"serial_no\",\r\n                    e.target.value\r\n                  )\r\n                }\r\n                placeholder=\"Serial No\"\r\n              />\r\n\r\n              <input\r\n                value={equipmentForm.make}\r\n                onChange={(e) =>\r\n                  updateEquipmentField(\r\n                    \"make\",\r\n                    e.target.value\r\n                  )\r\n                }\r\n                placeholder=\"Make\"\r\n              />\r\n\r\n              <input\r\n                value={equipmentForm.campus}\r\n                onChange={(e) =>\r\n                  updateEquipmentField(\r\n                    \"campus\",\r\n                    e.target.value\r\n                  )\r\n                }\r\n                placeholder=\"Campus\"\r\n              />\r\n\r\n              <input\r\n                value={equipmentForm.contract}\r\n                onChange={(e) =>\r\n                  updateEquipmentField(\r\n                    \"contract\",\r\n                    e.target.value\r\n                  )\r\n                }\r\n                placeholder=\"Contract\"\r\n              />\r\n\r\n              <label>\r\n                PM 1 Date\r\n                <div className=\"flex items-center gap-2\">\r\n                  <input\r\n                    type=\"date\"\r\n                    value={equipmentForm.pm1_date}\r\n                    disabled={equipmentForm.pm1_na}\r\n                    onChange={(e) =>\r\n                      setEquipmentForm({\r\n                        ...equipmentForm,\r\n                        pm1_date: e.target.value,\r\n                        pm1_na: false,\r\n                      })\r\n                    }\r\n                  />\r\n                  <label className=\"flex items-center gap-1\">\r\n                    <input\r\n                      type=\"checkbox\"\r\n                      checked={equipmentForm.pm1_na}\r\n                      onChange={(e) =>\r\n                        setEquipmentForm({\r\n                          ...equipmentForm,\r\n                          pm1_na: e.target.checked,\r\n                          pm1_date: e.target.checked ? \"\" : equipmentForm.pm1_date,\r\n                        })\r\n                      }\r\n                    />\r\n                    N/A\r\n                  </label>\r\n                </div>\r\n              </label>\r\n\r\n              <label>\r\n                PM 2 Date\r\n                <div className=\"flex items-center gap-2\">\r\n                  <input\r\n                    type=\"date\"\r\n                    value={equipmentForm.pm2_date}\r\n                    disabled={equipmentForm.pm2_na}\r\n                    onChange={(e) =>\r\n                      setEquipmentForm({\r\n                        ...equipmentForm,\r\n                        pm2_date: e.target.value,\r\n                        pm2_na: false,\r\n                      })\r\n                    }\r\n                  />\r\n                  <label className=\"flex items-center gap-1\">\r\n                    <input\r\n                      type=\"checkbox\"\r\n                      checked={equipmentForm.pm2_na}\r\n                      onChange={(e) =>\r\n                        setEquipmentForm({\r\n                          ...equipmentForm,\r\n                          pm2_na: e.target.checked,\r\n                          pm2_date: e.target.checked ? \"\" : equipmentForm.pm2_date,\r\n                        })\r\n                      }\r\n                    />\r\n                    N/A\r\n                  </label>\r\n                </div>\r\n              </label>\r\n\r\n              <label>\r\n                PM 3 Date\r\n                <div className=\"flex items-center gap-2\">\r\n                  <input\r\n                    type=\"date\"\r\n                    value={equipmentForm.pm3_date}\r\n                    disabled={equipmentForm.pm3_na}\r\n                    onChange={(e) =>\r\n                      setEquipmentForm({\r\n                        ...equipmentForm,\r\n                        pm3_date: e.target.value,\r\n                        pm3_na: false,\r\n                      })\r\n                    }\r\n                  />\r\n                  <label className=\"flex items-center gap-1\">\r\n                    <input\r\n                      type=\"checkbox\"\r\n                      checked={equipmentForm.pm3_na}\r\n                      onChange={(e) =>\r\n                        setEquipmentForm({\r\n                          ...equipmentForm,\r\n                          pm3_na: e.target.checked,\r\n                          pm3_date: e.target.checked ? \"\" : equipmentForm.pm3_date,\r\n                        })\r\n                      }\r\n                    />\r\n                    N/A\r\n                  </label>\r\n                </div>\r\n              </label>\r\n\r\n              <label>\r\n                PM 4 Date\r\n                <div className=\"flex items-center gap-2\">\r\n                  <input\r\n                    type=\"date\"\r\n                    value={equipmentForm.pm4_date}\r\n                    disabled={equipmentForm.pm4_na}\r\n                    onChange={(e) =>\r\n                      setEquipmentForm({\r\n                        ...equipmentForm,\r\n                        pm4_date: e.target.value,\r\n                        pm4_na: false,\r\n                      })\r\n                    }\r\n                  />\r\n                  <label className=\"flex items-center gap-1\">\r\n                    <input\r\n                      type=\"checkbox\"\r\n                      checked={equipmentForm.pm4_na}\r\n                      onChange={(e) =>\r\n                        setEquipmentForm({\r\n                          ...equipmentForm,\r\n                          pm4_na: e.target.checked,\r\n                          pm4_date: e.target.checked ? \"\" : equipmentForm.pm4_date,\r\n                        })\r\n                      }\r\n                    />\r\n                    N/A\r\n                  </label>\r\n                </div>\r\n              </label>\r\n            </div>\r\n\r\n            <div className=\"actions\">\r\n              <button\r\n                className=\"btn primary\"\r\n                onClick={saveEquipment}\r\n              >\r\n                <Save size={15} />\r\n                Save\r\n              </button>\r\n\r\n              <button\r\n                className=\"btn\"\r\n                onClick={() =>\r\n                  setShowEquipmentForm(false)\r\n                }\r\n              >\r\n                Cancel\r\n              </button>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      )}\r\n\r\n      {editingPM && (\r\n        <div className=\"overlay\">\r\n          <div className=\"authbox\">\r\n            <button\r\n              className=\"close\"\r\n              onClick={() => {\r\n                setEditingPM(null);\r\n                setPmDate(\"\");\r\n              }}\r\n            >\r\n              <X />\r\n            </button>\r\n\r\n            <h2>\r\n              Edit PM {editingPM.pm_no} Date\r\n            </h2>\r\n\r\n            <label>\r\n              Scheduled Date\r\n            </label>\r\n\r\n            <input\r\n              type=\"date\"\r\n              value={pmDate}\r\n              onChange={(e) =>\r\n                setPmDate(e.target.value)\r\n              }\r\n            />\r\n\r\n            <div className=\"actions\">\r\n              <button\r\n                className=\"btn primary\"\r\n                onClick={savePMDate}\r\n              >\r\n                <Save size={15} />\r\n                Save Date\r\n              </button>\r\n\r\n              <button\r\n                className=\"btn\"\r\n                onClick={() => {\r\n                  setEditingPM(null);\r\n                  setPmDate(\"\");\r\n                }}\r\n              >\r\n                Cancel\r\n              </button>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      )}\r\n\r\n      {authOpen && (\r\n        <div className=\"overlay\">\r\n          <div className=\"authbox\">\r\n            <button\r\n              className=\"close\"\r\n              onClick={() =>\r\n                setAuthOpen(false)\r\n              }\r\n            >\r\n              <X />\r\n            </button>\r\n\r\n            <h2>Sign in</h2>\r\n\r\n            <form onSubmit={handleLogin}>\r\n              <div className=\"login-methods\">\r\n                <button\r\n                  type=\"button\"\r\n                  className={\r\n                    loginType === \"loginId\"\r\n                      ? \"login-method active\"\r\n                      : \"login-method\"\r\n                  }\r\n                  onClick={() => {\r\n                    setLoginType(\"loginId\");\r\n                    setError(\"\");\r\n                  }}\r\n                >\r\n                  Login ID\r\n                </button>\r\n\r\n                <button\r\n                  type=\"button\"\r\n                  className={\r\n                    loginType === \"email\"\r\n                      ? \"login-method active\"\r\n                      : \"login-method\"\r\n                  }\r\n                  onClick={() => {\r\n                    setLoginType(\"email\");\r\n                    setError(\"\");\r\n                  }}\r\n                >\r\n                  Email\r\n                </button>\r\n              </div>\r\n\r\n              {loginType === \"loginId\" ? (\r\n                <div className=\"login-field\">\r\n                  <label htmlFor=\"loginId\">Login ID</label>\r\n                  <input\r\n                    id=\"loginId\"\r\n                    type=\"text\"\r\n                    value={loginId}\r\n                    onChange={(e) => setLoginId(e.target.value)}\r\n                    placeholder=\"Enter Login ID\"\r\n                    autoComplete=\"username\"\r\n                    disabled={loading}\r\n                  />\r\n                </div>\r\n              ) : (\r\n                <div className=\"login-field\">\r\n                  <label htmlFor=\"email\">Email Address</label>\r\n                  <input\r\n                    id=\"email\"\r\n                    type=\"email\"\r\n                    value={email}\r\n                    onChange={(e) => setEmail(e.target.value)}\r\n                    placeholder=\"Enter email address\"\r\n                    autoComplete=\"username\"\r\n                    disabled={loading}\r\n                  />\r\n                </div>\r\n              )}\r\n\r\n              <div className=\"login-field\">\r\n                <label htmlFor=\"password\">Password</label>\r\n                <input\r\n                  id=\"password\"\r\n                  type=\"password\"\r\n                  value={password}\r\n                  onChange={(e) => setPassword(e.target.value)}\r\n                  placeholder=\"Enter password\"\r\n                  autoComplete=\"current-password\"\r\n                  disabled={loading}\r\n                />\r\n              </div>\r\n\r\n              <div className=\"authmsg\">\r\n                {error || authMessage}\r\n              </div>\r\n\r\n              <div className=\"actions\">\r\n                <button\r\n                  type=\"submit\"\r\n                  className=\"btn primary\"\r\n                  disabled={loading}\r\n                >\r\n                  {loading ? \"Signing in...\" : \"Sign in\"}\r\n                </button>\r\n\r\n              <button\r\n                type=\"button\"\r\n                className=\"btn\"\r\n                onClick={signUp}\r\n              >\r\n                Sign up\r\n              </button>\r\n\r\n              <button\r\n                type=\"button\"\r\n                className=\"btn\"\r\n                onClick={resetPassword}\r\n              >\r\n                Reset password\r\n              </button>\r\n              </div>\r\n            </form>\r\n          </div>\r\n        </div>\r\n      )}\r\n    </main>\r\n  );\r\n}\r\n\r\nfunction Stat({\r\n  label,\r\n  value,\r\n  hint,\r\n  icon,\r\n  danger,\r\n  warning,\r\n  success,\r\n  progress,\r\n}: {\r\n  label: string;\r\n  value: string | number;\r\n  hint: string;\r\n  icon: React.ReactNode;\r\n  danger?: boolean;\r\n  warning?: boolean;\r\n  success?: boolean;\r\n  progress?: number;\r\n}) {\r\n  const statusClass = danger\r\n    ? \"kpi-danger\"\r\n    : warning\r\n    ? \"kpi-warning\"\r\n    : success\r\n    ? \"kpi-success\"\r\n    : \"\";\r\n\r\n  return (\r\n    <div className={`stat kpi-card ${statusClass}`}>\r\n      <div className=\"statTop kpi-card-header\">\r\n        <span className=\"kpi-label\">{label}</span>\r\n\r\n        <i className=\"stat-card-icon kpi-card-icon\">\r\n          {icon}\r\n        </i>\r\n      </div>\r\n\r\n      <strong\r\n        className={`kpi-value ${\r\n          danger\r\n            ? \"redText\"\r\n            : warning\r\n            ? \"orangeText\"\r\n            : success\r\n            ? \"greenText\"\r\n            : \"\"\r\n          }`}\r\n      >\r\n        {value}\r\n      </strong>\r\n\r\n      <small className=\"kpi-subtitle\">{hint}</small>\r\n\r\n      {progress !== undefined && (\r\n        <div className=\"kpi-progress\" aria-hidden=\"true\">\r\n          <div\r\n            className=\"kpi-progress-bar\"\r\n            style={{\r\n              width: `${Math.min(100, Math.max(0, progress))}%`,\r\n            }}\r\n          />\r\n        </div>\r\n      )}\r\n    </div>\r\n  );\r\n}\r\n\r\nfunction ChartHeading({\r\n  title,\r\n  subtitle,\r\n  icon,\r\n}: {\r\n  title: string;\r\n  subtitle: string;\r\n  icon: React.ReactNode;\r\n}) {\r\n  return (\r\n    <div className=\"card-heading\">\r\n      <div>\r\n        <h2>{title}</h2>\r\n        <p>{subtitle}</p>\r\n      </div>\r\n      {icon}\r\n    </div>\r\n  );\r\n}\r\n\r\nfunction PerformanceRow({\r\n  label,\r\n  value,\r\n  percentage,\r\n}: {\r\n  label: string;\r\n  value: number;\r\n  percentage: number;\r\n}) {\r\n  return (\r\n    <div className=\"pm-performance-row\">\r\n      <div className=\"pm-performance-label\">{label}</div>\r\n      <div className=\"pm-performance-bar\">\r\n        <div\r\n          className=\"pm-performance-fill\"\r\n          style={{ width: `${Math.min(100, Math.max(0, percentage))}%` }}\r\n        />\r\n      </div>\r\n      <div className=\"pm-performance-value\">\r\n        {value}{percentage !== value ? `%` : \"\"}\r\n      </div>\r\n    </div>\r\n  );\r\n}\r\n\r\nfunction SummaryItem({\r\n  className,\r\n  icon,\r\n  value,\r\n  label,\r\n}: {\r\n  className: string;\r\n  icon: React.ReactNode;\r\n  value: number;\r\n  label: string;\r\n}) {\r\n  return (\r\n    <div className={`summary-item ${className}`}>\r\n      {icon}\r\n      <strong>{value}</strong>\r\n      <span>{label}</span>\r\n    </div>\r\n  );\r\n}\r\n\r\nfunction WorkloadCard({\r\n  className,\r\n  icon,\r\n  label,\r\n  value,\r\n  hint,\r\n  onClick,\r\n}: {\r\n  className: string;\r\n  icon: React.ReactNode;\r\n  label: string;\r\n  value: number;\r\n  hint: string;\r\n  onClick?: () => void;\r\n}) {\r\n  return (\r\n    <button type=\"button\" className={`workload-card ${className}`} onClick={onClick}>\r\n      {icon}\r\n      <div>\r\n        <span>{label}</span>\r\n        <strong>{value}</strong>\r\n        <small>{hint}</small>\r\n      </div>\r\n      <ChevronRight size={20} />\r\n    </button>\r\n  );\r\n}\r\n\r\nfunction StatusPanel({\r\n  title,\r\n  subtitle,\r\n  rows,\r\n  status,\r\n  onClose,\r\n  updatePM,\r\n}: {\r\n  title: string;\r\n  subtitle: string;\r\n  rows: { equipment: Equipment; pm: PMSchedule }[];\r\n  status: \"Pending\" | \"Overdue\";\r\n  onClose: () => void;\r\n  updatePM: (pm: PMSchedule, completed: boolean) => void;\r\n}) {\r\n  return (\r\n    <section className=\"dashboard-card due-panel\">\r\n      <div className=\"card-heading\">\r\n        <div>\r\n          <h2>{title}</h2>\r\n          <p>{subtitle}</p>\r\n        </div>\r\n        <button onClick={onClose} className=\"icon-button\" aria-label=\"Close\">\r\n          <X size={18} />\r\n        </button>\r\n      </div>\r\n      <div className=\"table-wrap due-soon-table\">\r\n        <table>\r\n          <thead><tr><th>Equipment</th><th>Inventory No</th><th>PM</th><th>Due Date</th><th>Status</th><th>Action</th></tr></thead>\r\n          <tbody>\r\n            {rows.map(({ equipment, pm }) => (\r\n              <tr key={pm.id}>\r\n                <td><strong>{equipment.equipment_name}</strong></td>\r\n                <td>{equipment.inventory_no}</td>\r\n                <td>PM {pm.pm_no}</td>\r\n                <td>{fmtDate(pm.scheduled_date)}</td>\r\n                <td><span className={`status ${status.toLowerCase()}`}>{status}</span></td>\r\n                <td>{status === \"Pending\" && <button className=\"btn btn-primary\" onClick={() => updatePM(pm, true)}>Mark Done</button>}</td>\r\n              </tr>\r\n            ))}\r\n          </tbody>\r\n        </table>\r\n      </div>\r\n    </section>\r\n  );\r\n}\r\n\r\nfunction Select({\r\n  value,\r\n  setValue,\r\n  options,\r\n  label,\r\n  any,\r\n}: {\r\n  value: string;\r\n  setValue: (x: string) => void;\r\n  options: string[];\r\n  label: string;\r\n  any?: string;\r\n}) {\r\n  return (\r\n    <select\r\n      value={value}\r\n      onChange={(e) =>\r\n        setValue(e.target.value)\r\n      }\r\n      aria-label={label}\r\n    >\r\n      <option>\r\n        {any ?? \"All\"}\r\n      </option>\r\n\r\n      {options.map((x) => (\r\n        <option key={x}>{x}</option>\r\n      ))}\r\n    </select>\r\n  );\r\n}\r\n\r\nfunction EquipmentRow({\r\n  e,\r\n  index,\r\n  showSection,\r\n  canManage,\r\n  canUpdate,\r\n  updatePM,\r\n  markAll,\r\n  openEquipmentForm,\r\n  deleteEquipment,\r\n  openPMDateEditor,\r\n}: {\r\n  e: Equipment;\r\n  index: number;\r\n  showSection: boolean;\r\n  canManage: boolean;\r\n  canUpdate: boolean;\r\n  updatePM: (\r\n    pm: PMSchedule,\r\n    completed: boolean\r\n  ) => void;\r\n  markAll: (e: Equipment) => void;\r\n  openEquipmentForm: (\r\n    e?: Equipment\r\n  ) => void;\r\n  deleteEquipment: (id: string) => void;\r\n  openPMDateEditor: (\r\n    pm: PMSchedule\r\n  ) => void;\r\n}) {\r\n  const pm = (n: number) =>\r\n    (e.pm_schedules ?? []).find(\r\n      (x) => x.pm_no === n\r\n    );\r\n\r\n  return (\r\n    <tr>\r\n      <td>{index + 1}</td>\r\n\r\n      {showSection && (\r\n        <td>\r\n          {e.section\r\n            ? getSectionLabel(e.section)\r\n            : \"-\"}\r\n        </td>\r\n      )}\r\n\r\n      <td>\r\n        <b>{e.department}</b>\r\n      </td>\r\n\r\n      <td>{e.inventory_no}</td>\r\n\r\n      <td>{e.location}</td>\r\n\r\n      <td>\r\n        <b>{e.equipment_name}</b>\r\n      </td>\r\n\r\n      <td>{e.model}</td>\r\n\r\n      <td>{e.serial_no}</td>\r\n\r\n      <td>{e.make}</td>\r\n\r\n      <td>\r\n        <span className=\"pill\">\r\n          {e.campus}\r\n        </span>\r\n      </td>\r\n\r\n      <td>\r\n        <span className=\"pill\">\r\n          {e.contract}\r\n        </span>\r\n      </td>\r\n\r\n      {[1, 2, 3, 4].map((n) => (\r\n        <td key={n}>\r\n          <PMCell\r\n            pm={pm(n)}\r\n            updatePM={updatePM}\r\n            canManage={canManage}\r\n            canUpdate={canUpdate}\r\n            openPMDateEditor={\r\n              openPMDateEditor\r\n            }\r\n          />\r\n\r\n          {n === 4 && canUpdate && (\r\n            <button\r\n              className=\"markAll\"\r\n              onClick={() =>\r\n                markAll(e)\r\n              }\r\n            >\r\n              ✓ Mark all PMs\r\n            </button>\r\n          )}\r\n        </td>\r\n      ))}\r\n\r\n      {canManage && (\r\n        <td>\r\n          <div className=\"row-actions\">\r\n            <button\r\n              className=\"edit-button\"\r\n              onClick={() =>\r\n                openEquipmentForm(e)\r\n              }\r\n            >\r\n              <Pencil size={14} />\r\n              Edit\r\n            </button>\r\n\r\n            <button\r\n              className=\"delete-button\"\r\n              onClick={() =>\r\n                deleteEquipment(e.id)\r\n              }\r\n            >\r\n              <Trash2 size={14} />\r\n              Delete\r\n            </button>\r\n          </div>\r\n        </td>\r\n      )}\r\n    </tr>\r\n  );\r\n}\r\n\r\nfunction PMCell({\r\n  pm,\r\n  updatePM,\r\n  canManage,\r\n  canUpdate,\r\n  openPMDateEditor,\r\n}: {\r\n  pm?: PMSchedule;\r\n  updatePM: (\r\n    pm: PMSchedule,\r\n    completed: boolean\r\n  ) => void;\r\n  canManage: boolean;\r\n  canUpdate: boolean;\r\n  openPMDateEditor: (\r\n    pm: PMSchedule\r\n  ) => void;\r\n}) {\r\n  if (!pm) {\r\n    return <span>—</span>;\r\n  }\r\n\r\n  const s = getPMStatus(pm);\r\n\r\n  if (pm.scheduled_date === null) {\r\n    return (\r\n      <div className=\"pmcell\">\r\n        <div className=\"pmdate\">N/A</div>\r\n\r\n        <span className=\"status\">N/A</span>\r\n\r\n        {canManage && (\r\n          <button\r\n            className=\"edit-button\"\r\n            onClick={() => openPMDateEditor(pm)}\r\n          >\r\n            <Pencil size={13} />\r\n            Edit Date\r\n          </button>\r\n        )}\r\n      </div>\r\n    );\r\n  }\r\n\r\n  return (\r\n    <div className=\"pmcell\">\r\n      <div className=\"pmdate\">\r\n        {pm.scheduled_date || \"N/A\"}\r\n      </div>\r\n\r\n      <span\r\n        className={`status ${s.toLowerCase()}`}\r\n      >\r\n        {s}\r\n      </span>\r\n\r\n      {canUpdate && (s === \"Done\" ? (\r\n        <button\r\n          className=\"undo\"\r\n          onClick={() =>\r\n            updatePM(pm, false)\r\n          }\r\n        >\r\n          ↶ Undo\r\n        </button>\r\n      ) : (\r\n        <button\r\n          className=\"mark\"\r\n          onClick={() =>\r\n            updatePM(pm, true)\r\n          }\r\n        >\r\n          ✓ Mark Done\r\n        </button>\r\n      ))}\r\n\r\n      {canManage && (\r\n        <button\r\n          className=\"edit-button\"\r\n          onClick={() =>\r\n            openPMDateEditor(pm)\r\n          }\r\n        >\r\n          <Pencil size={13} />\r\n          Edit Date\r\n        </button>\r\n      )}\r\n    </div>\r\n  );\r\n}\r\n\r\nfunction getSectionLabel(section: string | null) {\r\n  switch (section) {\r\n    case \"HIGH_END_RADIOLOGY\":\r\n      return \"High-End & Radiology\";\r\n    case \"LIFE_SUPPORT\":\r\n      return \"Life Support and Surgical\";\r\n    case \"GENERAL_MONITORING\":\r\n      return \"General Monitoring\";\r\n    default:\r\n      return \"All Sections\";\r\n  }\r\n}"],"names":["emptyStats","Done","Overdue","Pending","Scheduled","emptyEquipmentForm","sno","department","inventory_no","location","equipment_name","model","serial_no","make","campus","contract","pm1_date","pm2_date","pm3_date","pm4_date","pm1_na","pm2_na","pm3_na","pm4_na","fmtDate","value","Intl","DateTimeFormat","day","month","year","format","Date","cleanDate","toISOString","slice","date","parse_date_code","y","String","m","padStart","d","text","trim","test","parsed","Number","isNaN","getTime","excelValue","row","names","keys","Object","name","found","find","key","toLowerCase","replace","undefined","Dashboard","router","equipment","setEquipment","search","setSearch","equipmentFilter","setEquipmentFilter","sectionFilter","setSectionFilter","setCampus","setDepartment","setContract","status","setStatus","pmNumber","setPmNumber","scheduleSearch","setScheduleSearch","dataLoading","setDataLoading","connected","setConnected","userEmail","setUserEmail","userRole","setUserRole","userSection","setUserSection","authOpen","setAuthOpen","loginType","setLoginType","loginId","setLoginId","email","setEmail","password","setPassword","authMessage","setAuthMessage","loading","setLoading","error","setError","showUserManagement","setShowUserManagement","newUser","setNewUser","login_id","role","section","creatingUser","setCreatingUser","userMessage","setUserMessage","showEquipmentForm","setShowEquipmentForm","showDueSoon","setShowDueSoon","showOverdue","setShowOverdue","editingEquipment","setEditingEquipment","equipmentForm","setEquipmentForm","importing","setImporting","editingPM","setEditingPM","pmDate","setPmDate","isSuperAdmin","isSuperViewer","isSectionAdmin","isTechnician","canManageEquipment","canUpdatePM","canAccessEqui