    {"offset": {"line": 5564, "column": 0}, "map": {"version":3,"sources":["file:///C:/Users/Steve%20Smart/Downloads/preventive-maintenance-fullstack/lib/pm.ts"],"sourcesContent":["import type { PMSchedule, PMStatus } from \"./types\";\r\n\r\nexport function getPMStatus(pm: PMSchedule): PMStatus {\r\n  if (!pm.scheduled_date) {\r\n    return \"N/A\";\r\n  }\r\n\r\n  if (pm.completed_date) {\r\n    return \"Done\";\r\n  }\r\n\r\n  const today = new Date();\r\n  today.setHours(0, 0, 0, 0);\r\n\r\n  const scheduled = new Date(`${pm.scheduled_date}T00:00:00`);\r\n\r\n  const diffDays = Math.ceil(\r\n    (scheduled.getTime() - today.getTime()) /\r\n      (1000 * 60 * 60 * 24)\r\n  );\r\n\r\n  if (diffDays < 0) return \"Overdue\";\r\n  if (diffDays <= 30) return \"Pending\";\r\n\r\n  return \"Scheduled\";\r\n}"],"names":["getPMStatus","pm","scheduled_date","completed_date","today","Date","setHours","scheduled","diffDays","Math","ceil","getTime"],"mappings":";;;;AAEO,SAASA,YAAYC,EAAc;IACxC,IAAI,CAACA,GAAGC,cAAc,EAAE;QACtB,OAAO;IACT;IAEA,IAAID,GAAGE,cAAc,EAAE;QACrB,OAAO;IACT;IAEA,MAAMC,QAAQ,IAAIC;IAClBD,MAAME,QAAQ,CAAC,GAAG,GAAG,GAAG;IAExB,MAAMC,YAAY,IAAIF,KAAK,GAAGJ,GAAGC,cAAc,CAAC,SAAS,CAAC;IAE1D,MAAMM,WAAWC,KAAKC,IAAI,CACxB,CAACH,UAAUI,OAAO,KAAKP,MAAMO,OAAO,EAAE,IACpC,CAAC,OAAO,KAAK,KAAK,EAAE;IAGxB,IAAIH,WAAW,GAAG,OAAO;IACzB,IAAIA,YAAY,IAAI,OAAO;IAE3B,OAAO;AACT"}},
